:root {
  --primary: #5b5bd6;
  --primary-dark: #4545b8;
  --primary-soft: #eeeeff;
  --accent: #7c3aed;
  --success: #16a34a;
  --warning: #d97706;
  --danger: #dc2626;
  --danger-soft: #fef2f2;
  --text: #171923;
  --muted: #6b7280;
  --line: #e5e7eb;
  --surface: #ffffff;
  --surface-soft: #f7f8fc;
  --sidebar: #ffffff;
  --shadow: 0 18px 60px rgba(26, 32, 64, 0.12);
  --radius: 20px;
}

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; }
body {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: var(--surface-soft);
  -webkit-font-smoothing: antialiased;
}
button, input, textarea, select { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .58; }
input, textarea, select { color: var(--text); }
.hidden { display: none !important; }
.mobile-only { display: none !important; }

.brand { display: inline-flex; align-items: center; gap: 10px; font-weight: 800; font-size: 19px; letter-spacing: -.02em; }
.brand-light { color: #fff; }
.brand-mark {
  width: 38px; height: 38px; border-radius: 13px; display: inline-grid; place-items: center;
  color: #fff; background: linear-gradient(135deg, #6c63ff, #8b5cf6); box-shadow: 0 8px 22px rgba(91, 91, 214, .3);
}
.eyebrow { font-size: 11px; letter-spacing: .16em; font-weight: 800; color: var(--primary); }

.primary-button, .secondary-button, .danger-button, .warning-button, .success-button {
  min-height: 44px; border-radius: 12px; padding: 0 17px; border: 1px solid transparent; font-weight: 750;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; transition: .18s ease;
}
.primary-button { color: #fff; background: linear-gradient(135deg, var(--primary), var(--accent)); box-shadow: 0 8px 20px rgba(91, 91, 214, .2); }
.primary-button:hover { transform: translateY(-1px); box-shadow: 0 12px 24px rgba(91, 91, 214, .26); }
.secondary-button { color: #34364a; background: #fff; border-color: var(--line); }
.secondary-button:hover { border-color: #c7c9d6; background: #fafaff; }
.danger-button { background: var(--danger); color: #fff; }
.warning-button { background: #fff7ed; color: #b45309; border-color: #fed7aa; }
.success-button { background: #ecfdf3; color: #15803d; border-color: #bbf7d0; }
.full-button { width: 100%; }
.icon-button {
  width: 40px; height: 40px; border-radius: 12px; border: 1px solid var(--line); background: #fff; color: #4b5563;
  display: inline-grid; place-items: center; font-size: 18px;
}
.icon-button:hover { background: #f5f5fb; color: var(--primary); }
.link-button { border: 0; padding: 0; background: transparent; color: var(--primary); font-weight: 700; }
.logout-button {
  width: calc(100% - 36px); margin: 12px 18px 18px; min-height: 42px; border: 1px solid #fecaca; background: #fff5f5; color: #b91c1c; border-radius: 12px; font-weight: 750;
}
.light-logout { background: rgba(255,255,255,.08); color: #fff; border-color: rgba(255,255,255,.13); }

/* Authentication */
.auth-page { min-height: 100vh; background: #eff1f8; }
.auth-shell { min-height: 100vh; display: grid; grid-template-columns: minmax(360px, .92fr) minmax(520px, 1.08fr); }
.auth-showcase {
  position: relative; overflow: hidden; padding: 42px clamp(32px, 6vw, 90px); color: #fff;
  background: radial-gradient(circle at 20% 20%, rgba(139,92,246,.7), transparent 34%), linear-gradient(145deg, #26235c, #4d46b8 55%, #6d48cb);
  display: flex; flex-direction: column; justify-content: space-between;
}
.auth-showcase::before, .auth-showcase::after { content: ""; position: absolute; border: 1px solid rgba(255,255,255,.14); border-radius: 50%; }
.auth-showcase::before { width: 430px; height: 430px; right: -220px; top: 14%; }
.auth-showcase::after { width: 280px; height: 280px; left: -130px; bottom: 5%; }
.showcase-copy, .showcase-points, .auth-showcase .brand { position: relative; z-index: 1; }
.showcase-copy { max-width: 560px; }
.showcase-copy .eyebrow { color: #ddd6fe; }
.showcase-copy h1 { font-size: clamp(42px, 5vw, 68px); line-height: 1.02; letter-spacing: -.055em; margin: 18px 0 22px; }
.showcase-copy p { font-size: 18px; line-height: 1.7; max-width: 520px; color: rgba(255,255,255,.78); }
.showcase-points { display: grid; gap: 14px; max-width: 570px; }
.showcase-points > div { display: flex; gap: 13px; align-items: flex-start; padding: 15px; border-radius: 16px; background: rgba(255,255,255,.08); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.1); }
.showcase-points > div > span { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: rgba(255,255,255,.15); font-weight: 900; }
.showcase-points p { margin: 0; display: grid; gap: 4px; }
.showcase-points small { color: rgba(255,255,255,.7); line-height: 1.45; }
.auth-card-wrap { display: grid; place-items: center; padding: 42px 24px; }
.auth-card { width: min(100%, 520px); background: #fff; border-radius: 26px; box-shadow: var(--shadow); padding: clamp(28px, 4vw, 48px); border: 1px solid rgba(229,231,235,.8); }
.auth-mobile-brand { display: none; margin-bottom: 28px; }
.auth-heading h2 { font-size: 31px; margin: 0 0 8px; letter-spacing: -.035em; }
.auth-heading p { margin: 0; color: var(--muted); }
.auth-tabs { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; padding: 5px; border-radius: 14px; background: #f0f1f7; margin: 28px 0 24px; }
.auth-tab { min-height: 42px; border: 0; border-radius: 10px; background: transparent; color: #696b7c; font-weight: 800; }
.auth-tab.active { background: #fff; color: var(--primary); box-shadow: 0 3px 12px rgba(31,35,64,.08); }
.auth-form { display: grid; gap: 17px; }
.field { display: grid; gap: 8px; }
.field > span { font-size: 13px; font-weight: 800; color: #3f4152; }
.field > span em { font-style: normal; color: #9ca3af; font-weight: 600; }
.field small { color: #8a8d9b; line-height: 1.35; }
.field-control { min-height: 48px; border: 1px solid #dcdfe8; border-radius: 13px; display: flex; align-items: center; background: #fff; transition: .18s ease; overflow: hidden; }
.field-control:focus-within { border-color: var(--primary); box-shadow: 0 0 0 4px rgba(91,91,214,.1); }
.field-control input { min-width: 0; flex: 1; border: 0; outline: 0; background: transparent; padding: 0 14px; }
.field-icon { color: #a0a3b2; width: 42px; text-align: center; font-weight: 900; border-right: 1px solid #eceef4; }
.password-toggle { align-self: stretch; border: 0; background: transparent; padding: 0 13px; color: var(--primary); font-size: 12px; font-weight: 800; }
.field textarea, .field select, .admin-filter input, .admin-filter select {
  width: 100%; min-height: 48px; border: 1px solid #dcdfe8; border-radius: 13px; outline: 0; background: #fff; padding: 12px 14px;
}
.field textarea { min-height: 100px; resize: vertical; }
.field textarea:focus, .field select:focus, .admin-filter input:focus, .admin-filter select:focus { border-color: var(--primary); box-shadow: 0 0 0 4px rgba(91,91,214,.1); }
.form-row-end { display: flex; justify-content: flex-end; margin-top: -4px; }
.form-message { min-height: 18px; margin: 0; color: var(--danger); font-size: 13px; font-weight: 650; line-height: 1.45; }
.form-message.success { color: var(--success); }
.button-loader { display: none; width: 17px; height: 17px; border: 2px solid rgba(255,255,255,.45); border-top-color: #fff; border-radius: 50%; animation: spin .7s linear infinite; }
.is-loading .button-loader { display: block; }
.is-loading > span:first-child { opacity: .7; }

/* Modal and toast */
.modal-backdrop { position: fixed; inset: 0; z-index: 1000; display: grid; place-items: center; padding: 20px; background: rgba(15,18,35,.58); backdrop-filter: blur(7px); animation: fadeIn .16s ease; }
.modal-card { width: min(100%, 560px); max-height: calc(100vh - 40px); overflow: auto; background: #fff; border-radius: 24px; box-shadow: 0 28px 90px rgba(0,0,0,.24); padding: 28px; animation: modalIn .2s ease; }
.modal-small { max-width: 460px; }
.modal-medium { max-width: 570px; }
.modal-card h3 { margin: 14px 0 8px; font-size: 22px; letter-spacing: -.025em; }
.modal-card > p { margin: 0 0 22px; color: var(--muted); line-height: 1.55; }
.modal-icon { width: 52px; height: 52px; border-radius: 17px; display: grid; place-items: center; background: var(--primary-soft); color: var(--primary); font-size: 24px; font-weight: 900; }
.shield-icon { background: #f3e8ff; color: #7e22ce; }
.danger-icon { background: var(--danger-soft); color: var(--danger); }
.modal-form { display: grid; gap: 16px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }
.modal-actions.single { justify-content: stretch; }
.modal-actions.single > button { flex: 1; }
.restriction-details { border-radius: 14px; background: #f8f8fc; border: 1px solid var(--line); padding: 14px; font-size: 13px; color: #55586b; line-height: 1.55; margin-bottom: 18px; }
.toast-container { position: fixed; right: 22px; bottom: 22px; z-index: 1300; display: grid; gap: 10px; width: min(360px, calc(100vw - 44px)); }
.toast { background: #202235; color: #fff; border-radius: 14px; padding: 14px 16px; box-shadow: 0 15px 40px rgba(15,18,35,.25); display: flex; gap: 11px; align-items: flex-start; animation: toastIn .2s ease; }
.toast.success { background: #166534; }
.toast.error { background: #991b1b; }
.toast strong { display: block; margin-bottom: 3px; }
.toast p { margin: 0; color: rgba(255,255,255,.82); font-size: 13px; line-height: 1.45; }

/* Main chat */
.app-page { height: 100vh; overflow: hidden; }
.app-shell { height: 100vh; display: grid; grid-template-columns: 330px minmax(0, 1fr); background: #eef0f7; }
.sidebar { min-width: 0; height: 100vh; background: var(--sidebar); border-right: 1px solid var(--line); display: flex; flex-direction: column; z-index: 20; }
.sidebar-top { height: 70px; flex: 0 0 70px; padding: 0 18px; border-bottom: 1px solid #eceef3; display: flex; align-items: center; justify-content: space-between; }
.me-card { margin: 14px 14px 10px; padding: 13px; display: flex; align-items: center; gap: 11px; background: linear-gradient(135deg, #f7f7ff, #f4f1ff); border: 1px solid #e7e4ff; border-radius: 16px; }
.me-card strong { display: block; font-size: 14px; }
.me-card small { display: block; margin-top: 2px; color: var(--success); font-size: 11px; font-weight: 750; }
.main-nav { padding: 4px 12px 0; display: grid; gap: 5px; }
.nav-item { width: 100%; min-height: 54px; border: 0; border-radius: 14px; background: transparent; color: #3f4252; padding: 8px 10px; display: flex; align-items: center; gap: 10px; text-align: left; }
.nav-item:hover { background: #f5f5fb; }
.nav-item.active { background: var(--primary-soft); color: var(--primary-dark); }
.nav-item > span:nth-child(2) { display: grid; flex: 1; gap: 2px; }
.nav-item strong { font-size: 13px; }
.nav-item small { color: #8a8d9c; font-size: 11px; }
.nav-icon { width: 35px; height: 35px; border-radius: 11px; display: grid; place-items: center; background: #fff; box-shadow: 0 2px 10px rgba(44,46,70,.08); }
.badge { min-width: 21px; height: 21px; padding: 0 6px; border-radius: 999px; background: var(--danger); color: #fff; font-size: 11px; display: grid; place-items: center; }
.sidebar-actions { padding: 10px 14px; }
.sidebar-scroll { min-height: 0; overflow-y: auto; flex: 1; padding: 2px 10px 18px; }
.sidebar-section { margin-top: 12px; }
.section-title { display: flex; align-items: center; justify-content: space-between; color: #797c8a; font-size: 11px; font-weight: 850; text-transform: uppercase; letter-spacing: .08em; padding: 0 8px 7px; }
.section-title b { min-width: 20px; height: 20px; padding: 0 5px; border-radius: 999px; background: #eceef4; display: grid; place-items: center; color: #6d7080; }
.section-toggle { width: 100%; border: 0; background: transparent; color: #747785; display: flex; align-items: center; justify-content: space-between; padding: 8px; font-size: 12px; font-weight: 800; }
.conversation-list, .compact-list { display: grid; gap: 4px; }
.conversation-item { position: relative; width: 100%; border: 0; background: transparent; border-radius: 13px; padding: 8px; display: flex; gap: 10px; align-items: center; text-align: left; color: var(--text); }
.conversation-item:hover { background: #f5f6fa; }
.conversation-item.active { background: #eeeeff; }
.conversation-item .conversation-copy { min-width: 0; flex: 1; display: grid; gap: 2px; }
.conversation-item strong { font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.conversation-item small { color: #8b8e9c; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.online-dot { width: 10px; height: 10px; border-radius: 50%; background: #22c55e; border: 2px solid #fff; position: absolute; left: 39px; top: 34px; }
.avatar { position: relative; flex: 0 0 auto; width: 40px; height: 40px; border-radius: 14px; display: grid; place-items: center; color: #fff; background: linear-gradient(135deg, #5b5bd6, #8b5cf6); font-weight: 900; text-transform: uppercase; box-shadow: 0 5px 14px rgba(91,91,214,.18); }
.avatar-lg { width: 45px; height: 45px; border-radius: 15px; }
.avatar-xl { width: 64px; height: 64px; border-radius: 20px; font-size: 22px; }
.world-avatar { background: linear-gradient(135deg, #0ea5e9, #6366f1); }
.admin-avatar { background: linear-gradient(135deg, #111827, #4b5563); }
.empty-compact { color: #9a9ca8; font-size: 12px; text-align: center; padding: 12px 8px; }
.request-card { border: 1px solid #e8e9f0; background: #fafaff; border-radius: 13px; padding: 10px; display: grid; gap: 9px; }
.request-user { display: flex; align-items: center; gap: 9px; }
.request-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.request-actions button { min-height: 31px; border-radius: 9px; border: 1px solid var(--line); font-size: 11px; font-weight: 800; }
.request-actions .accept { background: var(--primary); color: #fff; border-color: var(--primary); }
.blocked-row { display: flex; align-items: center; gap: 8px; padding: 8px; border-radius: 12px; background: #fafafa; }
.blocked-row strong { font-size: 12px; flex: 1; }
.blocked-row button { border: 0; background: transparent; color: var(--primary); font-size: 11px; font-weight: 800; }

.chat-panel { min-width: 0; height: 100vh; display: grid; grid-template-rows: 74px minmax(0, 1fr) auto auto; background: #f8f9fc; }
.chat-header { padding: 0 22px; display: flex; align-items: center; gap: 12px; background: rgba(255,255,255,.94); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
.chat-heading { min-width: 0; flex: 1; }
.chat-heading h1 { margin: 0; font-size: 17px; letter-spacing: -.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chat-heading p { margin: 4px 0 0; font-size: 11px; color: #8a8d9c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chat-header-actions { display: flex; align-items: center; gap: 8px; }
.messages { min-height: 0; overflow-y: auto; padding: 24px clamp(18px, 4vw, 54px); display: flex; flex-direction: column; gap: 12px; scroll-behavior: smooth; }
.conversation-loading, .empty-conversation { margin: auto; text-align: center; color: #8b8e9d; }
.spinner { width: 30px; height: 30px; border: 3px solid #e5e7eb; border-top-color: var(--primary); border-radius: 50%; display: inline-block; animation: spin .8s linear infinite; }
.message-row { display: flex; align-items: flex-end; gap: 9px; max-width: min(78%, 760px); }
.message-row.mine { align-self: flex-end; flex-direction: row-reverse; }
.message-row.other { align-self: flex-start; }
.message-bubble { padding: 10px 13px; border-radius: 17px; background: #fff; border: 1px solid #e8e9ef; box-shadow: 0 3px 12px rgba(31,35,64,.05); min-width: 72px; }
.message-row.mine .message-bubble { background: linear-gradient(135deg, var(--primary), #6f55d9); color: #fff; border-color: transparent; }
.message-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.message-meta strong { font-size: 11px; }
.message-meta time { font-size: 10px; color: #9a9daa; }
.message-row.mine .message-meta time { color: rgba(255,255,255,.7); }
.message-text { white-space: pre-wrap; word-break: break-word; font-size: 14px; line-height: 1.48; }
.message-attachment { margin-top: 8px; overflow: hidden; border-radius: 12px; background: rgba(255,255,255,.12); }
.message-attachment img, .message-attachment video { display: block; max-width: min(360px, 100%); max-height: 320px; object-fit: contain; background: #111827; }
.file-attachment { display: flex; align-items: center; gap: 10px; padding: 10px; color: inherit; text-decoration: none; min-width: 210px; }
.file-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: rgba(91,91,214,.12); font-weight: 900; }
.message-row.mine .file-icon { background: rgba(255,255,255,.18); }
.file-attachment div { min-width: 0; }
.file-attachment strong, .file-attachment small { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.file-attachment strong { font-size: 12px; }
.file-attachment small { font-size: 10px; opacity: .75; margin-top: 2px; }
.typing-indicator { padding: 0 clamp(18px, 4vw, 54px) 8px; color: #777a88; font-size: 12px; font-style: italic; }
.composer-wrap { padding: 10px clamp(14px, 3vw, 34px) 18px; background: #f8f9fc; }
.composer { min-height: 56px; border: 1px solid #dde0e8; border-radius: 18px; background: #fff; padding: 7px; display: flex; align-items: flex-end; gap: 7px; box-shadow: 0 8px 30px rgba(31,35,64,.07); }
.composer:focus-within { border-color: #b9b9f5; box-shadow: 0 0 0 4px rgba(91,91,214,.08), 0 8px 30px rgba(31,35,64,.07); }
.composer textarea { flex: 1; min-width: 0; min-height: 40px; max-height: 140px; padding: 10px 4px; border: 0; outline: 0; resize: none; background: transparent; line-height: 1.4; }
.attach-button { flex: 0 0 40px; border: 0; background: #f3f4f9; font-size: 22px; }
.send-button { width: 42px; height: 42px; flex: 0 0 42px; border-radius: 13px; border: 0; background: linear-gradient(135deg, var(--primary), var(--accent)); color: #fff; font-size: 17px; box-shadow: 0 7px 16px rgba(91,91,214,.24); }
.message-counter { align-self: center; color: #a0a2ae; font-size: 10px; }
.attachment-preview { margin: 0 0 8px; background: #fff; border: 1px solid var(--line); border-radius: 13px; padding: 9px 11px; display: flex; align-items: center; gap: 9px; box-shadow: 0 5px 18px rgba(31,35,64,.06); }
.attachment-preview .preview-copy { min-width: 0; flex: 1; }
.attachment-preview strong, .attachment-preview small { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.attachment-preview strong { font-size: 12px; }
.attachment-preview small { margin-top: 2px; color: #8a8d9a; font-size: 10px; }
.attachment-preview button { border: 0; background: transparent; color: var(--danger); font-size: 18px; }
.action-list { display: grid; gap: 8px; margin: 18px 0; }
.action-list button { width: 100%; border: 1px solid var(--line); background: #fff; border-radius: 14px; padding: 13px; display: flex; align-items: center; gap: 12px; text-align: left; }
.action-list button:hover { background: #f8f8fc; }
.action-list button > span { width: 38px; height: 38px; border-radius: 11px; background: #f0f1f7; display: grid; place-items: center; }
.action-list button div { display: grid; gap: 3px; }
.action-list strong { font-size: 13px; }
.action-list small { color: var(--muted); line-height: 1.35; }
.action-list .danger-action { color: var(--danger); }
.choice-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.choice-card { border: 1px solid var(--line); border-radius: 14px; padding: 13px; display: flex; gap: 9px; align-items: flex-start; }
.choice-card:has(input:checked) { border-color: var(--primary); background: var(--primary-soft); }
.choice-card span { display: grid; gap: 3px; }
.choice-card strong { font-size: 13px; }
.choice-card small { color: var(--muted); line-height: 1.35; }

/* Support */
.support-page { min-height: 100vh; background: radial-gradient(circle at top left, #eeeaff, transparent 34%), #f2f4f9; padding: 24px; }
.support-shell { width: min(100%, 1100px); margin: 0 auto; }
.support-header { height: 60px; display: flex; align-items: center; justify-content: space-between; }
.support-card { height: calc(100vh - 108px); min-height: 610px; margin-top: 18px; background: #fff; border: 1px solid #e5e7ef; border-radius: 26px; box-shadow: var(--shadow); display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto auto; overflow: hidden; }
.support-info { padding: 24px 28px 16px; display: flex; gap: 17px; align-items: center; }
.support-info h1 { margin: 5px 0 5px; font-size: 25px; letter-spacing: -.035em; }
.support-info p { margin: 0; color: var(--muted); }
.support-account { margin: 0 28px 12px; border: 1px solid #e7e8ef; border-radius: 14px; background: #fafaff; padding: 12px 14px; font-size: 12px; color: #5e6170; display: flex; gap: 18px; flex-wrap: wrap; }
.support-messages { border-top: 1px solid #eceef3; background: #f8f9fc; }
.support-composer { margin: 0 24px 22px; }

/* Admin */
.admin-page { height: 100vh; overflow: hidden; background: #f0f2f7; }
.admin-shell { height: 100vh; display: grid; grid-template-columns: 320px minmax(0, 1fr); }
.admin-sidebar { min-width: 0; height: 100vh; display: flex; flex-direction: column; background: #202133; color: #fff; z-index: 25; }
.admin-sidebar .sidebar-top { border-bottom-color: rgba(255,255,255,.08); }
.admin-profile { margin: 16px; padding: 13px; border-radius: 15px; background: rgba(255,255,255,.07); display: flex; align-items: center; gap: 10px; }
.admin-profile strong, .admin-profile small { display: block; }
.admin-profile small { margin-top: 3px; color: rgba(255,255,255,.55); font-size: 10px; }
.admin-filter { display: grid; gap: 8px; padding: 0 16px 12px; }
.admin-filter input, .admin-filter select { min-height: 42px; border-color: rgba(255,255,255,.1); background: rgba(255,255,255,.08); color: #fff; }
