/* ===== NexChat smart responsive upgrade ===== */
html { color-scheme: light; }
body { min-width: 280px; }
.brand { text-decoration: none; color: inherit; }
.brand-logo { width: 40px; height: 40px; display: block; filter: drop-shadow(0 8px 16px rgba(65,65,170,.18)); }
.brand-mark { display: none; }
.auth-showcase-top, .auth-card-top { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.auth-card-top { margin-bottom: 24px; }
.auth-mobile-brand { margin: 0; }
.feature-icon { font-size: 15px; }

.language-picker {
  min-width: 0; height: 40px; display: inline-flex; align-items: center; gap: 7px; padding: 0 10px;
  border: 1px solid var(--line); border-radius: 12px; background: #fff; color: var(--text);
}
.language-picker select { min-width: 110px; max-width: 150px; border: 0; outline: 0; background: transparent; color: inherit; font-weight: 750; cursor: pointer; }
.language-picker-dark { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.18); color: #fff; backdrop-filter: blur(12px); }
.language-picker-dark select option { color: #111827; }
.auth-language-picker { display: none; }
.sidebar-language { margin: 0 18px 8px; width: calc(100% - 36px); }
.sidebar-language select { flex: 1; max-width: none; }
.sidebar-footer { margin-top: auto; padding-top: 8px; border-top: 1px solid #eceef3; background: #fff; }
.sidebar-footer .logout-button { display: flex; gap: 8px; margin-top: 0; }

.page-loader {
  position: fixed; inset: 0; z-index: 5000; display: grid; place-items: center; align-content: center; gap: 18px;
  background: radial-gradient(circle at 50% 40%, #f1efff, #f8f9fc 60%); transition: opacity .28s ease, visibility .28s ease;
}
.page-loader.loaded { opacity: 0; visibility: hidden; pointer-events: none; }
.page-loader img { width: 76px; height: 76px; animation: loaderFloat 1.4s ease-in-out infinite alternate; }
.loader-ring { width: 34px; height: 34px; border: 3px solid #dddafe; border-top-color: var(--primary); border-radius: 50%; animation: spin .72s linear infinite; }
@keyframes loaderFloat { to { transform: translateY(-7px) scale(1.03); } }

.success-modal-card { overflow: hidden; position: relative; text-align: center; }
.success-modal-icon { margin: 0 auto; background: #ecfdf3; color: #15803d; }
.success-confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.success-confetti i { position: absolute; top: -18px; width: 8px; height: 18px; border-radius: 4px; animation: confettiFall 2.4s linear infinite; }
.success-confetti i:nth-child(1){left:12%;background:#6c63ff;animation-delay:.1s}.success-confetti i:nth-child(2){left:28%;background:#f59e0b;animation-delay:.45s}.success-confetti i:nth-child(3){left:45%;background:#10b981;animation-delay:.8s}.success-confetti i:nth-child(4){left:63%;background:#ec4899;animation-delay:.25s}.success-confetti i:nth-child(5){left:78%;background:#0ea5e9;animation-delay:1s}.success-confetti i:nth-child(6){left:90%;background:#8b5cf6;animation-delay:.6s}
@keyframes confettiFall { 0%{transform:translateY(-20px) rotate(0);opacity:0}10%{opacity:1}100%{transform:translateY(560px) rotate(520deg);opacity:0} }

.me-card { min-width: 0; }
.me-copy { min-width: 0; flex: 1; }
.me-copy strong, .me-copy small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.me-copy small { color: var(--muted); }
.online-label { color: var(--success); }
.avatar-logo { background: linear-gradient(135deg,#5b5bd6,#8b5cf6); color: #fff; }
.blocked-copy { min-width: 0; flex: 1; }
.blocked-copy strong, .blocked-copy small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.blocked-copy small { color: var(--muted); font-size: 10px; }

.chat-panel { position: relative; }
.chat-header { min-width: 0; }
.chat-heading { min-width: 0; flex: 1; }
.chat-heading h1, .chat-heading p { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-header-actions { flex: 0 0 auto; }
.message-search-bar {
  height: 52px; flex: 0 0 52px; display: flex; align-items: center; gap: 10px; padding: 0 clamp(14px,3vw,34px);
  border-bottom: 1px solid var(--line); background: #fff; animation: searchDrop .16s ease;
}
.message-search-bar input { flex: 1; min-width: 0; height: 36px; border: 0; outline: 0; background: #f5f6fa; border-radius: 10px; padding: 0 12px; }
.message-search-bar button { width: 34px; height: 34px; border: 0; border-radius: 10px; background: #f4f4fa; color: #6b7280; }
@keyframes searchDrop { from { opacity: 0; transform: translateY(-7px); } }

.messages { position: relative; background: #f5f6fa; transition: background .22s ease; }
.messages.private-theme { background-position: center; background-size: cover; background-attachment: local; }
.messages.private-theme::before { content:""; position: fixed; pointer-events:none; inset: 70px 0 82px 330px; background: rgba(8,12,30,.17); z-index: 0; }
.messages.private-theme > * { position: relative; z-index: 1; }
.messages.theme-aurora { background-image: url('/chat-bg-aurora.svg?v=1.0.0'); }
.messages.theme-sunset { background-image: url('/chat-bg-sunset.svg?v=1.0.0'); }
.messages.theme-ocean { background-image: url('/chat-bg-ocean.svg?v=1.0.0'); }
.messages.theme-forest { background-image: url('/chat-bg-forest.svg?v=1.0.0'); }
.messages.theme-lavender { background-image: url('/chat-bg-lavender.svg?v=1.0.0'); }
.messages.theme-midnight { background-image: url('/chat-bg-midnight.svg?v=1.0.0'); }
.messages.theme-rose { background-image: url('/chat-bg-rose.svg?v=1.0.0'); }
.messages.private-theme .message-bubble { background: rgba(255,255,255,.92); border-color: rgba(255,255,255,.6); backdrop-filter: blur(12px); }
.messages.private-theme .message-row.mine .message-bubble { background: linear-gradient(135deg,rgba(91,91,214,.96),rgba(111,85,217,.96)); }
.messages.private-theme .delivery-status { color: rgba(255,255,255,.88); text-shadow: 0 1px 8px rgba(0,0,0,.35); }

.message-column { min-width: 0; display: grid; gap: 4px; }
.message-row.mine .message-column { justify-items: end; }
.message-bubble { position: relative; overflow: visible; word-break: break-word; }
.message-copy {
  position: absolute; top: 4px; right: -34px; width: 28px; height: 28px; border: 0; border-radius: 9px;
  background: rgba(255,255,255,.95); color: #6b7280; box-shadow: 0 6px 18px rgba(31,35,64,.12); opacity: 0; transform: scale(.9); transition: .15s ease;
}
.message-row.mine .message-copy { right: auto; left: -34px; }
.message-bubble:hover .message-copy, .message-copy:focus-visible { opacity: 1; transform: scale(1); }
.delivery-status { font-size: 10px; color: #8a8d9b; font-weight: 700; padding: 0 4px; }
.delivery-status.seen { color: #5b5bd6; }
.search-hidden { display: none !important; }
.message-avatar { flex: 0 0 auto; }

.typing-indicator { min-height: 34px; display: flex; align-items: center; gap: 7px; font-style: normal; background: #f8f9fc; }
.typing-avatar { width: 23px; height: 23px; border-radius: 50%; display: grid; place-items: center; background: #ecebff; font-size: 11px; }
.typing-dots { display: inline-flex; align-items: center; gap: 3px; }
.typing-dots i { width: 5px; height: 5px; border-radius: 50%; background: #7c7f8f; animation: typingPulse .9s infinite ease-in-out; }
.typing-dots i:nth-child(2){animation-delay:.14s}.typing-dots i:nth-child(3){animation-delay:.28s}
@keyframes typingPulse { 0%,60%,100%{transform:translateY(0);opacity:.45}30%{transform:translateY(-4px);opacity:1} }

.emoji-picker {
  position: absolute; left: clamp(58px,8vw,110px); bottom: 78px; z-index: 20; width: min(330px,calc(100vw - 24px));
  display: grid; grid-template-columns: repeat(6,1fr); gap: 4px; padding: 10px; border: 1px solid var(--line);
  border-radius: 16px; background: rgba(255,255,255,.98); box-shadow: 0 20px 55px rgba(22,26,54,.2); backdrop-filter: blur(15px);
}
.emoji-picker button { aspect-ratio: 1; border: 0; border-radius: 10px; background: transparent; font-size: 21px; }
.emoji-picker button:hover { background: #f0efff; transform: scale(1.08); }
.send-button.sending { animation: sendPulse .8s ease infinite alternate; }
@keyframes sendPulse { to { transform: scale(.9); opacity:.7; } }

.scroll-bottom-button {
  position: absolute; right: 24px; bottom: 104px; z-index: 15; width: 42px; height: 42px; border: 1px solid #dddfea;
  border-radius: 50%; background: #fff; color: var(--primary); font-size: 22px; box-shadow: 0 12px 28px rgba(31,35,64,.18);
}

.theme-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }
.theme-card { position: relative; padding: 0; border: 2px solid transparent; border-radius: 16px; overflow: hidden; background: #f7f8fc; text-align: left; }
.theme-card > span { display: block; aspect-ratio: 2.15/1; background-size: cover; background-position: center; }
.theme-card strong { display: block; padding: 10px 12px; font-size: 12px; }
.theme-card i { position: absolute; right: 9px; top: 9px; width: 25px; height: 25px; border-radius: 50%; display: grid; place-items:center; background:#fff; color:var(--primary); font-style:normal; box-shadow:0 6px 16px rgba(0,0,0,.15); }
.theme-card.active { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(91,91,214,.1); }

.toast { position: relative; padding-right: 40px; }
.toast > button { position:absolute; right:10px; top:8px; border:0; background:transparent; color:rgba(255,255,255,.7); font-size:20px; }
.toast-icon { flex: 0 0 24px; width:24px; height:24px; border-radius:50%; display:grid; place-items:center; background:rgba(255,255,255,.14); }

