/* NexChat Smart v4 */
:root{--panel:#fff;--soft:#f5f6fb;--ink:#17182b;--muted:#70758d;--line:#e5e7f0;--accent:#6557e8;--accent2:#8d55f5;--danger:#e04755;--success:#1fa77a}
