/* Smooth sign-in success */
.login-success-card { text-align: center; overflow: hidden; position: relative; padding: 34px 30px 30px; }
.login-success-card::before { content: ""; position: absolute; width: 220px; height: 220px; left: 50%; top: -150px; transform: translateX(-50%); border-radius: 50%; background: radial-gradient(circle, rgba(99,102,241,.18), transparent 70%); pointer-events: none; }
.login-success-visual { width: 78px; height: 78px; margin: 0 auto 12px; position: relative; display: grid; place-items: center; }
.login-success-ring { position: absolute; inset: 0; border: 4px solid #e7e7ff; border-top-color: var(--primary); border-right-color: #8b5cf6; border-radius: 50%; animation: loginSuccessSpin .8s cubic-bezier(.65,.05,.36,1) infinite; transition: .35s ease; }
.login-success-check { width: 58px; height: 58px; display: grid; place-items: center; border-radius: 50%; color: #fff; background: linear-gradient(135deg,#22c55e,#16a34a); font-size: 30px; font-weight: 900; opacity: 0; transform: scale(.45) rotate(-18deg); transition: opacity .3s ease, transform .42s cubic-bezier(.2,.9,.25,1.35); box-shadow: 0 12px 28px rgba(34,197,94,.25); }
.login-success-card h3 { margin-top: 8px; }
.login-success-card p { margin-bottom: 20px; }
.login-success-progress { height: 5px; overflow: hidden; border-radius: 999px; background: #ececff; }
.login-success-progress span { display: block; width: 100%; height: 100%; border-radius: inherit; background: linear-gradient(90deg,var(--primary),#8b5cf6,#22c55e); transform-origin: left; animation: loginSuccessProgress 1.25s linear forwards; }
#loginSuccessModal.is-complete .login-success-ring { opacity: 0; transform: scale(.65); animation-play-state: paused; }
#loginSuccessModal.is-complete .login-success-check { opacity: 1; transform: scale(1) rotate(0); }
@keyframes loginSuccessSpin { to { transform: rotate(360deg); } }
@keyframes loginSuccessProgress { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@media (prefers-reduced-motion: reduce) { .login-success-ring, .login-success-progress span { animation-duration: .01ms; animation-iteration-count: 1; } }


/* Discoverable conversation and message actions */
.conversation-quick-actions{display:flex;align-items:center;gap:8px;padding:8px 16px;border-bottom:1px solid rgba(224,226,238,.8);background:rgba(255,255,255,.86);backdrop-filter:blur(12px);overflow-x:auto;scrollbar-width:none;flex:0 0 auto}
.conversation-quick-actions::-webkit-scrollbar{display:none}
.conversation-quick-actions button{display:inline-flex;align-items:center;gap:6px;border:1px solid #e3e5ef;background:#fff;color:#4a4d63;border-radius:999px;padding:8px 12px;white-space:nowrap;cursor:pointer;box-shadow:0 4px 12px rgba(42,44,82,.06);transition:.18s ease}
.conversation-quick-actions button:hover{transform:translateY(-1px);border-color:#b8b2f7;color:#5d50d8}
.conversation-quick-actions button span{font-size:15px}.conversation-quick-actions button b{font-size:12px}
.feature-hint{display:flex;align-items:center;gap:10px;margin:10px 16px 0;padding:10px 12px;border:1px solid #ddd9ff;border-radius:14px;background:linear-gradient(135deg,#f8f7ff,#fff);color:#55586f;box-shadow:0 8px 22px rgba(91,78,210,.08)}
.feature-hint>span{font-size:20px}.feature-hint p{flex:1;margin:0;font-size:12px;line-height:1.45}.feature-hint button{border:0;background:transparent;color:#85889d;cursor:pointer;font-size:16px}
.message-more{opacity:.58;transform:translateY(-50%) scale(.96)}
.message-bubble:hover .message-more,.message-bubble:focus-within .message-more,.message-more:focus-visible{opacity:1;transform:translateY(-50%) scale(1)}
@media (hover:none),(pointer:coarse){
  .message-more{opacity:1;position:static;transform:none!important;display:inline-grid;place-items:center;float:right;margin:-5px -7px -4px 8px;min-width:30px;min-height:30px;background:rgba(255,255,255,.2);box-shadow:none;color:inherit}
  .message-row.other .message-more{position:static;float:right;margin:-5px -7px -4px 8px}
  .message-bubble {padding-right:10px;cursor:pointer}
}
@media (max-width:700px){
