/* ========================================================================
   NEXCHAT 8.0 — VISUAL REFRESH & RELIABLE GLOBAL CONFIRMATION
   ======================================================================== */
:root {
  --primary: #6557e8;
  --primary-dark: #4f46c7;
  --primary-soft: #efedff;
  --accent: #8b5cf6;
  --accent-cyan: #20c7c8;
  --surface: rgba(255,255,255,.88);
  --surface-solid: #ffffff;
  --surface-muted: #f6f7fc;
  --text: #24243b;
  --muted: #777b91;
  --line: rgba(106,102,150,.14);
  --danger: #e3485a;
  --danger-soft: #fff0f2;
  --success: #15a76f;
  --shadow-soft: 0 14px 42px rgba(37,34,83,.10);
  --shadow-strong: 0 26px 90px rgba(31,28,74,.20);
}

html { color-scheme: light; }
body { text-rendering: optimizeLegibility; -webkit-font-smoothing: antialiased; }
button, input, textarea, select { font: inherit; }
button { -webkit-tap-highlight-color: transparent; }
button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 3px solid rgba(101,87,232,.22);
  outline-offset: 2px;
}

/* Shared glass surfaces */
.auth-card,
.smart-sidebar,
.smart-chat-panel,
.admin-workspace,
.stats-grid article,
.support-card {
  border-color: rgba(121,113,183,.15) !important;
  box-shadow: var(--shadow-soft);
}

.primary-button, .send-button {
  background: linear-gradient(135deg, #6557e8 0%, #7b5ce7 52%, #9b5fe0 100%);
  box-shadow: 0 10px 24px rgba(101,87,232,.25);
  transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
}
.primary-button:hover, .send-button:hover { transform: translateY(-1px); filter: saturate(1.08); box-shadow: 0 14px 28px rgba(101,87,232,.31); }
.primary-button:active, .send-button:active { transform: translateY(0) scale(.98); }
.secondary-button { transition: border-color .18s ease, background .18s ease, transform .18s ease; }
.secondary-button:hover { border-color: rgba(101,87,232,.36); background: #f8f7ff; transform: translateY(-1px); }
.danger-button { background: linear-gradient(135deg,#f05c6d,#d9364c); box-shadow: 0 10px 24px rgba(227,72,90,.22); }

/* Login / register */
.auth-page {
  background:
    radial-gradient(circle at 10% 12%, rgba(92,74,232,.22), transparent 32%),
    radial-gradient(circle at 88% 82%, rgba(32,199,200,.16), transparent 34%),
    linear-gradient(135deg,#f6f5ff 0%,#f8fbff 48%,#fff8fc 100%);
}
.auth-showcase {
  background:
    radial-gradient(circle at 20% 10%, rgba(255,255,255,.20), transparent 28%),
    radial-gradient(circle at 85% 86%, rgba(46,219,202,.24), transparent 34%),
    linear-gradient(145deg,#2f2b72 0%,#5447c8 46%,#7952d3 72%,#b05ac1 100%);
}
.auth-showcase::before { border-color: rgba(255,255,255,.20); box-shadow: inset 0 0 70px rgba(255,255,255,.05); animation: showcaseRingFloat 16s ease-in-out infinite; }
.auth-showcase::after { border-color: rgba(255,255,255,.12); animation: showcaseRingFloat 12s ease-in-out infinite reverse; }
.auth-showcase::selection { background: rgba(255,255,255,.24); }
.auth-showcase::marker { color: transparent; }
.auth-showcase {
  overflow: hidden;
  background-size: 160% 160%;
  animation: showcaseGradientShift 14s ease-in-out infinite;
}
.auth-showcase .brand,
.showcase-copy,
.showcase-points,
.showcase-hover-stack { position: relative; z-index: 2; }
.auth-showcase::after,
.auth-showcase::before { will-change: transform; }
.auth-showcase::before,
.auth-showcase::after { opacity: .95; }
.auth-showcase .showcase-copy { position: relative; }
.auth-showcase .showcase-copy::after {
  content:"";
  position:absolute;
  width: 240px;
  height: 240px;
  right: -24px;
  top: 26px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.18), rgba(255,255,255,0) 68%);
  filter: blur(10px);
  animation: auroraPulse 8.5s ease-in-out infinite alternate;
  pointer-events:none;
}
.showcase-points > div {
  transition: transform .25s ease, box-shadow .25s ease, background .25s ease, border-color .25s ease;
}
.showcase-points > div:hover {
  transform: translateY(-4px);
  background: rgba(255,255,255,.12);
  border-color: rgba(255,255,255,.20);
  box-shadow: 0 18px 38px rgba(20,16,62,.18);
}
.showcase-hover-stack {
  display: grid;
  gap: 14px;
  width: min(340px, 90%);
  margin: 22px 0 18px;
}
.showcase-hover-card {
  position: relative;
  overflow: hidden;
  padding: 16px 18px;
  border-radius: 20px;
  background: linear-gradient(135deg, rgba(255,255,255,.16), rgba(255,255,255,.08));
  border: 1px solid rgba(255,255,255,.18);
  box-shadow: 0 18px 40px rgba(23,19,74,.18);
  backdrop-filter: blur(16px) saturate(1.18);
  transition: transform .28s ease, box-shadow .28s ease, border-color .28s ease;
}
.showcase-hover-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 0%, rgba(255,255,255,.16) 45%, transparent 75%);
  transform: translateX(-120%);
  transition: transform .7s ease;
}
.showcase-hover-card:hover { transform: translateY(-5px) scale(1.01); box-shadow: 0 24px 48px rgba(20,16,62,.24); border-color: rgba(255,255,255,.28); }
.showcase-hover-card:hover::before { transform: translateX(120%); }
.showcase-hover-card strong,
.showcase-hover-card small,
.showcase-hover-badge,
.showcase-mini-avatars,
.showcase-hover-card div { position: relative; z-index: 1; }
.showcase-hover-card strong { display:block; font-size: 18px; line-height: 1.3; margin-bottom: 6px; }
.showcase-hover-card small { color: rgba(255,255,255,.74); line-height: 1.5; }
.showcase-hover-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  margin-bottom: 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .02em;
  background: rgba(255,255,255,.14);
  color: rgba(255,255,255,.94);
}
.showcase-hover-card-main { animation: floatCardA 6s ease-in-out infinite; }
.showcase-hover-card-mini {
  display:flex;
  align-items:center;
  gap:14px;
  width: min(290px, 92%);
  margin-left: auto;
  animation: floatCardB 7s ease-in-out infinite;
}
.showcase-mini-avatars { display:flex; align-items:center; }
.showcase-mini-avatars span {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display:grid;
  place-items:center;
  margin-left: -8px;
  border: 2px solid rgba(255,255,255,.65);
  color:#fff;
  font-size: 12px;
  font-weight: 900;
  background: linear-gradient(135deg, rgba(255,255,255,.35), rgba(255,255,255,.08));
  box-shadow: 0 8px 20px rgba(31,24,86,.18);
}
.showcase-mini-avatars span:first-child { margin-left: 0; }
.auth-card-wrap { position: relative; isolation: isolate; }
.auth-card-wrap::before {
  content:""; position:absolute; width:320px; height:320px; border-radius:50%;
  background:linear-gradient(135deg,rgba(101,87,232,.14),rgba(32,199,200,.08));
  filter:blur(30px); z-index:-1; animation:authGlowFloat 8s ease-in-out infinite alternate;
}
.auth-card {
  background: rgba(255,255,255,.90);
  backdrop-filter: blur(22px) saturate(1.2);
  border-radius: 30px;
  padding: clamp(28px,4vw,48px);
  box-shadow: 0 30px 90px rgba(45,39,105,.16);
  animation: authCardIn .62s cubic-bezier(.2,.85,.25,1) both;
}
.auth-heading h2 { font-size: clamp(28px,3vw,36px); background:linear-gradient(135deg,#292744,#6d55d6); -webkit-background-clip:text; background-clip:text; color:transparent; }
.auth-tabs { padding:6px; border-radius:17px; background:#f0eff9; border:1px solid rgba(101,87,232,.08); }
.auth-tab { min-height:45px; border-radius:12px; transition:.2s ease; }
.auth-tab.active { color:#5646d0; box-shadow:0 7px 18px rgba(43,38,94,.10); }
.field-control {
  border-radius:15px !important;
  background:#fbfbfe !important;
  border:1px solid rgba(90,87,130,.16) !important;
  transition:border-color .18s ease,box-shadow .18s ease,background .18s ease,transform .18s ease;
}
.field-control:focus-within { background:#fff !important; border-color:rgba(101,87,232,.62) !important; box-shadow:0 0 0 4px rgba(101,87,232,.10); transform:translateY(-1px); }
.field-icon { filter:saturate(.85); }
.auth-form .primary-button { min-height:50px; border-radius:15px; font-weight:850; letter-spacing:.01em; }
.brand-logo { filter: drop-shadow(0 8px 14px rgba(59,49,154,.20)); }

/* Main app shell */
.smart-app-page {
  background:
    radial-gradient(circle at 3% 0%,rgba(101,87,232,.18),transparent 28%),
    radial-gradient(circle at 100% 100%,rgba(32,199,200,.12),transparent 31%),
    linear-gradient(135deg,#f1f2fb,#f8f9fd 52%,#f7f2fb);
}
