/* Dedicated, guaranteed logout confirmation */
.global-confirm-backdrop { z-index:5000; background:rgba(19,18,42,.63); backdrop-filter:blur(12px) saturate(.85); }
.global-confirm-card {
  width:min(100%,445px); position:relative; overflow:hidden; padding:30px;
