.global-confirm-actions button { min-height:47px; border-radius:14px; font-weight:850; }
.confirm-logout-button { display:flex; align-items:center; justify-content:center; gap:8px; }
.confirm-button-spinner { display:none; width:17px; height:17px; border:2px solid rgba(255,255,255,.45); border-top-color:#fff; border-radius:50%; animation:spin .65s linear infinite; }
.logout-progress-track { height:4px; border-radius:999px; background:#f1edf5; overflow:hidden; margin-top:15px; opacity:0; transition:opacity .2s ease; }
.logout-progress-track span { display:block; height:100%; width:100%; transform:translateX(-100%); border-radius:inherit; background:linear-gradient(90deg,#6557e8,#e3485a); }
.global-confirm-backdrop.logout-processing .confirm-button-spinner { display:block; }
.global-confirm-backdrop.logout-processing .logout-progress-track { opacity:1; }
.global-confirm-backdrop.logout-processing .logout-progress-track span { animation:logoutProgress .48s ease forwards; }
.global-confirm-backdrop.logout-processing .global-confirm-icon { animation:confirmIconPulse .9s ease-in-out infinite alternate; }
.global-confirm-backdrop.logout-processing .global-confirm-actions button { opacity:.72; cursor:wait; }

/* Page loader polish */
.page-loader { background:linear-gradient(145deg,#f7f6ff,#fff); }
.page-loader img { width:72px; height:72px; filter:drop-shadow(0 16px 24px rgba(80,65,185,.24)); animation:loaderLogoFloat 1.3s ease-in-out infinite alternate; }
