/* Motion */
@keyframes authGlowFloat { to { transform:translate(28px,-18px) scale(1.08); } }
@keyframes authCardIn { from { opacity:0; transform:translateY(18px) scale(.985); } }
@keyframes messageRise { from { opacity:0; transform:translateY(7px) scale(.992); } }
@keyframes presenceGlow { 50% { box-shadow:0 0 0 5px rgba(30,203,131,.17); } }
@keyframes logoutArrow { 50% { transform:translateX(4px); } }
