@keyframes confirmIconPulse { to { transform:scale(1.035); box-shadow:0 16px 35px rgba(227,72,90,.18); } }
@keyframes loaderLogoFloat { to { transform:translateY(-4px) scale(1.025); } }

/* Responsive polish */
@media (max-width: 900px) {
  .smart-shell { margin:0; border-radius:0; box-shadow:none; }
