.effect-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.effect-choice{display:grid;grid-template-columns:72px 1fr auto;align-items:center;gap:12px;min-height:82px;padding:10px 12px;text-align:left;position:relative;overflow:hidden}.effect-choice>span:nth-child(2) strong,.effect-choice>span:nth-child(2) small{display:block}.effect-choice>span:nth-child(2) small{margin-top:3px;color:#85899e;font-size:10px;line-height:1.35}.effect-choice>i{font-style:normal;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#6a58e8;color:#fff}.effect-choice:hover{transform:translateY(-2px);box-shadow:0 13px 28px rgba(45,39,104,.12)}.effect-choice.active{background:linear-gradient(145deg,#fff,#f5f2ff)}
.effect-preview-bubble{display:grid!important;place-items:center!important;width:68px!important;min-width:68px!important;height:46px!important;padding:0!important;border-radius:16px 16px 6px 16px!important;color:#fff!important;font-weight:900!important;font-size:15px!important;pointer-events:none!important;margin:0!important}.effect-choice[data-effect="none"] .effect-preview-bubble{background:#eef0f6!important;color:#666b7e!important;box-shadow:none!important;border:1px solid #e2e5ee!important}
.effect-access-active{color:#fff!important;background:linear-gradient(135deg,#6757e9,#9b5cda)!important;box-shadow:0 8px 22px rgba(105,87,232,.27)!important}.effect-unlocked{animation:effectUnlocked 1.7s cubic-bezier(.2,.8,.2,1)}

/* Extra polish for special bubble effects */
.message-bubble.effect-neon{animation:neonBreathe 2.5s ease-in-out infinite}.message-bubble.effect-fire{background-size:180% 180%!important;animation:fireFlow 3.2s ease-in-out infinite}.message-bubble.effect-ice::after{content:"❄";position:absolute;right:7px;top:-10px;font-size:13px;color:#dff5ff;animation:iceDrift 2.8s ease-in-out infinite}.message-bubble.effect-galaxy::after{content:"✦";position:absolute;left:10px;top:4px;color:#fff7a8;font-size:9px;animation:galaxyTwinkle 1.9s ease-in-out infinite}.message-bubble.effect-shadow:hover{transform:translate(-2px,-2px)}

@keyframes interiorOrbA{to{transform:translate(calc(34px + var(--pointer-x)),calc(24px + var(--pointer-y))) scale(1.08)}}
