/* NexChat 8.4 — classic monochrome icons */
.icon-sprite {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}
.classic-icon {
  width: 1em;
  height: 1em;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.field-icon {
  display: grid;
  place-items: center;
  flex: 0 0 42px;
  color: #777b91;
  font-size: 18px;
  filter: none !important;
}
.field-control:focus-within .field-icon { color: var(--primary); }
.field-icon .classic-icon { width: 18px; height: 18px; }
.language-icon {
  display: grid;
  place-items: center;
  color: currentColor;
  font-size: 16px;
}
.language-icon .classic-icon { width: 16px; height: 16px; }
.feature-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 10px;
  color: rgba(255,255,255,.92);
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.16);
  font-size: 17px !important;
}
.feature-icon .classic-icon { width: 18px; height: 18px; }
.modal-icon .classic-icon { width: 24px; height: 24px; }
.showcase-badge-icon { width: 14px; height: 14px; display: inline-block; vertical-align: -2px; margin-right: 4px; }


