/* =========================================================
   NexChat V8.7 · Intelligent Motion System
   Smooth, device-aware motion for the whole authenticated UI
   ========================================================= */
:root{
  --motion-ease:cubic-bezier(.22,.9,.28,1);
  --motion-spring:cubic-bezier(.16,1,.3,1);
  --motion-fast:180ms;
  --motion-normal:360ms;
  --motion-slow:760ms;
  --ambient-x:50%;
  --ambient-y:34%;
  --tilt-x:0deg;
  --tilt-y:0deg;
  --lift-y:0px;
}

.smart-app-page,.admin-page,.support-page{
  isolation:isolate;
  background:
    radial-gradient(circle at var(--ambient-x) var(--ambient-y),rgba(112,88,232,.12),transparent 29%),
    radial-gradient(circle at 8% 85%,rgba(28,196,202,.09),transparent 30%),
    linear-gradient(135deg,#f4f5fb 0%,#fafbff 49%,#f4f1fb 100%);
  background-attachment:fixed;
}
.smart-app-page::before,.admin-page::before,.support-page::before{
  content:"";position:fixed;inset:0;z-index:-3;pointer-events:none;opacity:.45;
  background-image:linear-gradient(rgba(92,84,173,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(92,84,173,.035) 1px,transparent 1px);
  background-size:34px 34px;
  mask-image:linear-gradient(to bottom,rgba(0,0,0,.85),transparent 96%);
  animation:gridDrift 24s linear infinite;
}
.smart-app-page::after,.admin-page::after,.support-page::after{
  content:"";position:fixed;inset:-28%;z-index:-4;pointer-events:none;filter:blur(80px);opacity:.26;
  background:conic-gradient(from 30deg at 50% 50%,#7463f2,#4bd5cf,#f387bc,#7463f2);
  animation:ambientRotate 30s linear infinite;
}

body:not(.motion-ready) .smart-shell,
body:not(.motion-ready) .admin-shell,
body:not(.motion-ready) .support-shell{opacity:0;transform:translateY(12px) scale(.992)}
.motion-ready .smart-shell,.motion-ready .admin-shell,.motion-ready .support-shell{
  animation:shellEnter .72s var(--motion-spring) both;
}

.interior-motion-layer{position:fixed;inset:0;z-index:-2;overflow:hidden;pointer-events:none;transform:translate3d(var(--pointer-x,0),var(--pointer-y,0),0);transition:transform .7s var(--motion-ease)}
.interior-motion-layer .motion-orb{position:absolute;border-radius:50%;filter:blur(3px);opacity:.6;will-change:transform}
.motion-orb-a{width:340px;height:340px;left:-120px;top:8%;background:radial-gradient(circle,rgba(108,91,232,.19),transparent 68%);animation:orbFloatA 17s ease-in-out infinite}
.motion-orb-b{width:430px;height:430px;right:-150px;top:22%;background:radial-gradient(circle,rgba(35,198,204,.15),transparent 68%);animation:orbFloatB 22s ease-in-out infinite}
.motion-orb-c{width:300px;height:300px;left:43%;bottom:-140px;background:radial-gradient(circle,rgba(241,91,164,.13),transparent 68%);animation:orbFloatC 19s ease-in-out infinite}
.interior-motion-layer>span{position:absolute;width:5px;height:5px;border-radius:50%;background:rgba(101,87,232,.32);box-shadow:0 0 16px rgba(101,87,232,.3);animation:particleDrift 10s ease-in-out infinite}
.interior-motion-layer>span:nth-of-type(1){left:12%;top:23%;animation-delay:-2s}.interior-motion-layer>span:nth-of-type(2){left:78%;top:14%;animation-delay:-6s}.interior-motion-layer>span:nth-of-type(3){left:68%;top:72%;animation-delay:-4s}.interior-motion-layer>span:nth-of-type(4){left:28%;top:82%;animation-delay:-8s}.interior-motion-layer>span:nth-of-type(5){left:48%;top:32%;animation-delay:-3s}.interior-motion-layer>span:nth-of-type(6){left:88%;top:48%;animation-delay:-7s}

/* Motion surfaces and intelligent tilt */
.motion-tilt{
  --card-rotate-x:0deg;--card-rotate-y:0deg;--card-lift:0px;
  transform:perspective(900px) rotateX(var(--card-rotate-x)) rotateY(var(--card-rotate-y)) translateY(var(--card-lift));
  transform-style:preserve-3d;transition:transform .26s var(--motion-ease),box-shadow .26s ease,border-color .26s ease;
  will-change:transform;
}
.motion-tilt:hover{--card-lift:-3px}
.motion-tilt>*{transform:translateZ(0)}
.motion-reveal{animation:smartReveal .5s var(--motion-spring) both;animation-delay:var(--reveal-delay,0ms)}

/* Refined global interactions */
button,a,.conversation-item,.admin-user-item,.person-card{ -webkit-tap-highlight-color:transparent }
button,.nav-item,.icon-button,.conversation-item,.admin-user-item,.person-card,.request-item,.request-message-card{
  position:relative;overflow:hidden;
}
.ui-ripple{
  position:absolute!important;width:12px;height:12px;border-radius:50%;pointer-events:none;z-index:20;
  background:radial-gradient(circle,rgba(255,255,255,.72),rgba(118,91,233,.22) 48%,transparent 70%);
  transform:translate(-50%,-50%) scale(0);animation:rippleWave .64s ease-out forwards;
}
.primary-button,.send-button,.badge-manage-button,.effect-grant-button{
  background-size:180% 180%;animation:buttonGradientFlow 7s ease infinite;
}
.primary-button::after,.send-button::after,.badge-manage-button::after{
  content:"";position:absolute;inset:-80% auto -80% -45%;width:32%;transform:rotate(18deg);
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);transition:left .5s var(--motion-ease);pointer-events:none;
}
.primary-button:hover::after,.send-button:hover::after,.badge-manage-button:hover::after{left:120%}
.icon-button,.nav-icon,.classic-icon-host{transition:transform .24s var(--motion-spring),color .2s ease,filter .2s ease}
.icon-button:hover .classic-icon-host,.nav-item:hover .nav-icon{transform:scale(1.09) rotate(-3deg)}

/* Sidebar, navigation and profile card */
.smart-sidebar,.admin-sidebar{
  box-shadow:14px 0 45px rgba(44,38,94,.08);transition:box-shadow .4s ease,transform .45s var(--motion-spring);
}
.sidebar-top .brand-logo,.support-header .brand-logo,.auth-mobile-brand .brand-logo{
  animation:brandBreathe 4.5s ease-in-out infinite;filter:drop-shadow(0 8px 13px rgba(92,74,212,.2));
}
.me-card{
  isolation:isolate;background:linear-gradient(145deg,rgba(255,255,255,.97),rgba(246,245,255,.94));
  border-color:rgba(103,87,224,.14);box-shadow:0 12px 28px rgba(48,41,105,.07);
}
.me-card::before{
  content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 12% 20%,rgba(113,92,232,.15),transparent 35%);opacity:0;transition:opacity .3s ease;
}
.me-card:hover::before{opacity:1}
.me-card:hover .me-card-chevron{transform:translateX(3px)}
.nav-item::before{
  content:"";position:absolute;left:0;top:16%;bottom:16%;width:3px;border-radius:0 8px 8px 0;background:linear-gradient(#6d5be8,#24c7c7);transform:scaleY(0);transition:transform .25s var(--motion-spring);
}
.nav-item:hover::before,.nav-item.active::before{transform:scaleY(1)}
.nav-item:hover{transform:translateX(2px)}
.nav-item.active{background:linear-gradient(90deg,rgba(104,86,229,.1),rgba(104,86,229,.025));box-shadow:inset 0 0 0 1px rgba(104,86,229,.08)}
.section-title b,.badge{animation:badgePulseSoft 2.8s ease-in-out infinite}

/* Conversation lists */
.conversation-item,.admin-user-item,.person-card,.request-item,.request-message-card,.badge-granted-user,.effect-granted-user{
  transition:transform .25s var(--motion-spring),box-shadow .25s ease,border-color .25s ease,background .25s ease;
}
.conversation-item::after,.admin-user-item::after,.person-card::after{
  content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,.42) 45%,transparent 65%);transform:translateX(-120%);transition:transform .65s ease;
}
.conversation-item:hover::after,.admin-user-item:hover::after,.person-card:hover::after{transform:translateX(120%)}
.conversation-item:hover,.person-card:hover,.request-item:hover,.request-message-card:hover{transform:translateY(-2px);box-shadow:0 13px 30px rgba(49,43,104,.1)}
.conversation-item.active{animation:activeConversationGlow 3s ease-in-out infinite}
.conversation-item.is-blocked{filter:saturate(.72)}
.conversation-item.is-blocked:hover{filter:saturate(.9)}

/* Chat panel and header */
.smart-chat-panel,.admin-chat-panel,.support-card{position:relative;isolation:isolate;overflow:hidden}
.smart-chat-panel::before,.admin-chat-panel::before,.support-card::before{
  content:"";position:absolute;z-index:-1;width:55%;height:34%;right:-18%;top:-18%;border-radius:50%;
  background:radial-gradient(circle,rgba(108,87,229,.1),transparent 69%);animation:chatAmbient 11s ease-in-out infinite;
}
.smart-chat-header,.admin-chat-header,.support-info{
  position:relative;overflow:hidden;
}
.smart-chat-header::after,.admin-chat-header::after,.support-info::after{
  content:"";position:absolute;left:-45%;bottom:0;width:42%;height:2px;background:linear-gradient(90deg,transparent,#6c59e8,#28c9c7,transparent);animation:headerLineTravel 5.5s ease-in-out infinite;
}
.header-avatar-shell:hover .smart-avatar,.public-profile-avatar:hover .smart-avatar{transform:scale(1.045) rotate(-1.5deg)}
.connection-pill,.connection-chip{box-shadow:0 7px 22px rgba(24,175,126,.1);animation:connectionBreathe 3s ease-in-out infinite}

/* Messages */
.messages{
  scroll-behavior:smooth;position:relative;
  background-image:radial-gradient(circle at 15% 15%,rgba(107,87,228,.035),transparent 25%),radial-gradient(circle at 86% 72%,rgba(34,199,199,.035),transparent 25%);
  background-size:130% 130%;animation:messageBackdrop 18s ease-in-out infinite alternate;
}
.message-row{transform-origin:bottom center;will-change:transform,opacity}
.message-row.mine{animation-name:messageFromRight}.message-row.other{animation-name:messageFromLeft}
.message-row.motion-reveal{animation-duration:.42s}
.message-bubble {
  transition:transform .22s var(--motion-spring),box-shadow .22s ease,filter .22s ease;
  transform-origin:bottom center;
}
.message-bubble:hover{transform:translateY(-1px) scale(1.008);filter:saturate(1.04)}
.message-row.mine .message-bubble:hover{box-shadow:0 13px 29px rgba(86,65,206,.19)}
.message-row.other .message-bubble:hover{box-shadow:0 13px 29px rgba(44,49,77,.12)}
.message-more{transform:scale(.82);opacity:.68;transition:transform .2s var(--motion-spring),opacity .2s ease}
.message-bubble:hover .message-more,.message-bubble:focus-within .message-more{transform:scale(1);opacity:1}
.message-status.sending i{box-shadow:0 0 0 0 rgba(107,87,229,.28);animation:sendingPulse 1.35s ease-in-out infinite}
.typing-dots i{animation-duration:1.15s!important;filter:drop-shadow(0 2px 4px rgba(104,86,229,.22))}
.message-reactions{animation:reactionPop .28s var(--motion-spring) both}
.reaction-pill:hover{transform:translateY(-2px) scale(1.05)}

/* Composer */
.composer{
  transition:box-shadow .28s ease,border-color .28s ease,transform .28s var(--motion-spring);
}
.composer:focus-within{box-shadow:0 16px 42px rgba(76,61,173,.14),0 0 0 3px rgba(103,86,229,.08);transform:translateY(-1px)}
.composer::before{
  content:"";position:absolute;left:10%;right:10%;top:0;height:1px;background:linear-gradient(90deg,transparent,#735ee8,#2bc6c7,transparent);transform:scaleX(0);transition:transform .35s ease;
}
.composer:focus-within::before{transform:scaleX(1)}
.send-button{box-shadow:0 10px 24px rgba(91,72,216,.26)}
.send-button:hover{transform:translateY(-2px) rotate(-2deg) scale(1.04);box-shadow:0 14px 30px rgba(91,72,216,.34)}
.send-button:active{transform:scale(.94)}
.attachment-preview{animation:attachmentSlide .34s var(--motion-spring) both}

/* Profile and special ranks */
.profile-cover-modern,.public-profile-cover{overflow:hidden}
.profile-cover-modern::after,.public-profile-cover::after{
  content:"";position:absolute;inset:-50%;background:linear-gradient(120deg,transparent 35%,rgba(255,255,255,.2) 48%,transparent 62%);transform:translateX(-55%) rotate(8deg);animation:coverLightSweep 8s ease-in-out infinite;
}
.profile-avatar-wrap-modern,.public-profile-avatar{animation:profileAvatarEnter .58s var(--motion-spring) both}
.profile-rank-vip{filter:drop-shadow(0 4px 9px rgba(100,73,223,.28))}
.profile-rank-legend{filter:drop-shadow(0 5px 11px rgba(190,0,43,.34))}
.profile-rank-badge:hover{transform:scale(1.12)!important;z-index:8}
.profile-info-card,.public-profile-details{transition:transform .25s var(--motion-spring),box-shadow .25s ease}
.profile-info-card:hover,.public-profile-details:hover{transform:translateY(-2px);box-shadow:0 14px 34px rgba(47,41,104,.1)}

/* Modal, toast and dropdown motion */
.modal-backdrop{animation:backdropBloom .24s ease both}
.modal-card{transform-origin:center 35%;animation:modalSpringIn .42s var(--motion-spring) both}
.modal-card::before{
  content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:linear-gradient(135deg,rgba(255,255,255,.38),transparent 30%);opacity:.72;
}
.modal-icon{animation:modalIconFloat 3s ease-in-out infinite}
.toast{animation:toastSpring .44s var(--motion-spring) both}
.toast::after{content:"";position:absolute;left:0;bottom:0;height:2px;width:100%;background:rgba(255,255,255,.42);transform-origin:left;animation:toastLife 4.2s linear forwards}
.choice-card:hover,.action-list button:hover,.message-menu-actions button:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(48,42,103,.1)}

/* Admin dashboard */
.admin-main{position:relative}
.admin-topbar h1{background:linear-gradient(90deg,#25233d,#6151ce,#208e9c,#25233d);background-size:220% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:titleGradient 9s linear infinite}
.stats-grid article{
  overflow:hidden;isolation:isolate;transition:transform .28s var(--motion-spring),box-shadow .28s ease,border-color .28s ease;
}
.stats-grid article::before{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 90% 8%,rgba(110,88,230,.14),transparent 42%);opacity:.55;transition:transform .4s ease,opacity .4s ease}
.stats-grid article::after{content:"";position:absolute;width:84px;height:84px;border-radius:50%;right:-38px;bottom:-44px;border:1px solid rgba(108,87,229,.14);transition:transform .4s var(--motion-spring)}
.stats-grid article:hover{transform:translateY(-5px);box-shadow:0 22px 48px rgba(39,34,87,.14);border-color:rgba(107,87,229,.18)}
.stats-grid article:hover::before{transform:scale(1.18);opacity:.9}.stats-grid article:hover::after{transform:scale(1.35)}
.stats-grid article strong{display:inline-block;transition:transform .28s var(--motion-spring);font-variant-numeric:tabular-nums}
.stats-grid article:hover strong{transform:translateY(-2px) scale(1.05)}
.stat-number-pop{animation:numberPop .44s var(--motion-spring)}
.effect-admin-console,.badge-admin-console,.admin-workspace{
  position:relative;overflow:hidden;transition:transform .3s var(--motion-spring),box-shadow .3s ease,border-color .3s ease;
}
.effect-admin-console:hover,.badge-admin-console:hover,.admin-workspace:hover{box-shadow:0 27px 64px rgba(41,35,92,.14);border-color:rgba(105,85,228,.16)}
.effect-admin-console::after,.badge-admin-console::after,.admin-workspace::after{
  content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;padding:1px;
  background:linear-gradient(120deg,transparent 18%,rgba(105,86,230,.28),rgba(35,198,199,.22),transparent 76%);background-size:220% 100%;
  mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:borderFlow 8s linear infinite;
}
.admin-user-item.active .smart-avatar{animation:activeAvatar 2.8s ease-in-out infinite}
.detail-heading{animation:detailReveal .48s var(--motion-spring) both}
.detail-list>div{transition:transform .22s ease,background .22s ease}.detail-list>div:hover{transform:translateX(3px);background:rgba(104,86,229,.045)}

/* Support */
.support-header{animation:supportHeaderDrop .55s var(--motion-spring) both}
.support-card{animation:supportCardEnter .7s var(--motion-spring) .08s both}
.support-info .admin-avatar{animation:adminAvatarAura 3.4s ease-in-out infinite}

/* Device-aware performance */
@media (hover:none),(pointer:coarse){
  .motion-tilt{transform:none!important}
  .conversation-item:hover,.person-card:hover,.request-item:hover,.request-message-card:hover,.stats-grid article:hover{transform:none}
  .conversation-item::after,.admin-user-item::after,.person-card::after{display:none}
  .message-bubble:hover{transform:none}
}
@media (max-width:900px){
  .smart-app-page::after,.admin-page::after,.support-page::after{opacity:.16;filter:blur(95px)}
  .interior-motion-layer>span:nth-of-type(n+4){display:none}
  .stats-grid article:hover{transform:none}
}
@media (max-width:560px){
  .smart-app-page::before,.admin-page::before,.support-page::before{background-size:27px 27px;opacity:.36}
  .interior-motion-layer .motion-orb{opacity:.36}
  .message-row.motion-reveal{animation-duration:.3s}
  .modal-card{animation-duration:.32s}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
  .smart-app-page::before,.smart-app-page::after,.admin-page::before,.admin-page::after,.support-page::before,.support-page::after,.interior-motion-layer{display:none!important}
  .motion-tilt,.motion-reveal{transform:none!important}
}

