/* V8.7 positioning guards for decorative layers */
.composer,.modal-card,.stats-grid article,.profile-cover-modern,.public-profile-cover,.toast{position:relative}
.page-inactive .interior-motion-layer,.page-inactive::before,.page-inactive::after{animation-play-state:paused!important}

/* =========================================================
   NexChat V8.8 · Elite Profile Experience
   VIP and LEGEND profiles are visually distinct.
   LEGEND always takes precedence when both grants are active.
   ========================================================= */
:root{
  --vip-ink:#3c287e;
  --vip-primary:#7357f4;
  --vip-secondary:#be66f3;
  --vip-gold:#f4d985;
  --legend-ink:#29070d;
  --legend-primary:#d20c35;
  --legend-secondary:#6d0019;
  --legend-gold:#ffd88a;
}

/* Priority badge: only one badge is rendered by JS, LEGEND before VIP. */
.rank-avatar{isolation:isolate;overflow:visible!important}
.rank-avatar::before,
.rank-avatar::after{content:"";position:absolute;pointer-events:none;border-radius:inherit;z-index:-1}
.rank-avatar.rank-vip::before{
  inset:-4px;
  background:conic-gradient(from 30deg,#8c6cff,#f4d985,#49d6e9,#b05af2,#8c6cff);
  animation:vipAvatarOrbit 8s linear infinite;
  filter:drop-shadow(0 0 9px rgba(117,87,244,.42));
}
.rank-avatar.rank-vip::after{
  inset:-1.5px;background:#fff;z-index:-1;
  box-shadow:0 8px 22px rgba(97,67,218,.23);
}
.rank-avatar.rank-legend::before{
  inset:-5px;
  background:conic-gradient(from 0deg,#42000e,#ff3157,#ffd88a,#8e001e,#ff5570,#42000e);
  animation:legendAvatarOrbit 4.8s linear infinite;
  filter:drop-shadow(0 0 12px rgba(222,20,57,.55));
}
.rank-avatar.rank-legend::after{
  inset:-1.5px;background:linear-gradient(145deg,#fff8ea,#fff,#ffe2e7);z-index:-1;
  box-shadow:0 0 0 1px rgba(255,216,138,.85),0 10px 28px rgba(121,0,27,.34);
}
.rank-avatar.rank-legend>b{position:relative;z-index:2;text-shadow:0 2px 10px rgba(80,0,18,.32)}

/* Tier chips */
.elite-tier-chip{
  --tier-a:var(--vip-primary);--tier-b:var(--vip-secondary);--tier-c:var(--vip-gold);
  position:relative;display:inline-flex;align-items:center;gap:8px;width:max-content;max-width:100%;
  padding:6px 11px 6px 7px;border:1px solid color-mix(in srgb,var(--tier-c) 60%,#fff);
  border-radius:999px;background:linear-gradient(125deg,color-mix(in srgb,var(--tier-a) 12%,#fff),#fff 45%,color-mix(in srgb,var(--tier-b) 11%,#fff));
  box-shadow:0 7px 18px color-mix(in srgb,var(--tier-a) 18%,transparent);overflow:hidden;vertical-align:middle;
}
.elite-tier-chip::after{content:"";position:absolute;inset:-40% auto -40% -38%;width:34%;transform:skewX(-22deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.92),transparent);animation:eliteChipSweep 4.8s ease-in-out infinite}
.elite-tier-chip>i{position:relative;z-index:1;width:25px;height:25px;border-radius:8px;display:grid;place-items:center;font:950 13px/1 Inter,system-ui;color:#fff;background:linear-gradient(145deg,var(--tier-a),var(--tier-b));box-shadow:inset 0 1px 0 rgba(255,255,255,.4),0 4px 10px color-mix(in srgb,var(--tier-a) 35%,transparent)}
.elite-tier-chip>span{position:relative;z-index:1;display:grid;min-width:0}
.elite-tier-chip b{font-size:10px;line-height:1.05;letter-spacing:.12em;color:var(--vip-ink)}
.elite-tier-chip small{margin-top:2px;font-size:9px;color:#756e8c;white-space:nowrap}
.elite-tier-chip.tier-legend{--tier-a:var(--legend-primary);--tier-b:var(--legend-secondary);--tier-c:var(--legend-gold);background:linear-gradient(125deg,#fff6e6,#fff 42%,#fff0f3);border-color:rgba(229,174,76,.72);box-shadow:0 8px 22px rgba(152,0,34,.2)}
.elite-tier-chip.tier-legend>i{border-radius:7px 11px 7px 11px;background:linear-gradient(145deg,#ff3d5e,#9e001f 58%,#4f000f);box-shadow:inset 0 1px 0 rgba(255,255,255,.42),0 0 0 1px rgba(255,216,138,.66),0 5px 13px rgba(141,0,30,.42);animation:legendEmblemFloat 2.8s ease-in-out infinite}
.elite-tier-chip.tier-legend b{color:#85001d;text-shadow:0 1px 0 #fff}
.elite-tier-chip.is-compact{gap:5px;padding:3px 7px 3px 4px;margin-left:6px;box-shadow:none;transform:translateY(-1px)}
.elite-tier-chip.is-compact>i{width:18px;height:18px;border-radius:6px;font-size:9px}
.elite-tier-chip.is-compact b{font-size:8px;letter-spacing:.08em}
.elite-tier-chip.is-admin{margin:5px 0 7px}

/* Sidebar owner card */
.me-card.rank-vip,
.me-card.rank-legend{position:relative;border-width:1px;overflow:hidden}
.me-card.rank-vip{
  border-color:rgba(139,103,244,.32);
  background:linear-gradient(130deg,rgba(255,255,255,.98),rgba(246,241,255,.96) 55%,rgba(237,250,255,.94));
  box-shadow:0 16px 38px rgba(87,62,190,.15);
}
.me-card.rank-vip::after{content:"VIP";position:absolute;right:12px;top:8px;font:900 31px/1 Inter;color:rgba(111,80,226,.045);letter-spacing:-.08em;pointer-events:none}
.me-card.rank-legend{
  border-color:rgba(211,31,65,.38);
  background:linear-gradient(128deg,#fffaf2,#fff 42%,#fff0f3 100%);
  box-shadow:0 18px 42px rgba(125,0,28,.18),inset 0 1px 0 rgba(255,255,255,.9);
}
.me-card.rank-legend::after{content:"LEGEND";position:absolute;right:9px;top:8px;font:950 25px/1 Inter;color:rgba(150,0,31,.055);letter-spacing:-.08em;pointer-events:none}
.me-card.rank-legend::before{background:linear-gradient(100deg,transparent 20%,rgba(255,216,138,.5) 49%,transparent 76%)}
.me-card .elite-tier-chip{grid-column:auto;margin:4px 0 0}

/* Conversation and discovery cards */
.conversation-item.rank-vip,
.person-card.rank-vip{border-color:rgba(121,91,232,.2)}
.conversation-item.rank-vip::after,
.person-card.rank-vip::after{content:"";position:absolute;inset:auto 12px 0;height:1px;background:linear-gradient(90deg,transparent,#8f6df1,#63d9e5,transparent);opacity:.68}
.conversation-item.rank-legend,
.person-card.rank-legend{border-color:rgba(208,24,57,.24);background:linear-gradient(105deg,rgba(255,255,255,.98),rgba(255,244,246,.96))}
.conversation-item.rank-legend::after,
.person-card.rank-legend::after{content:"";position:absolute;inset:0 auto 0 0;width:3px;border-radius:4px;background:linear-gradient(#ff6b81,#a30024,#ffd88a);box-shadow:0 0 10px rgba(217,19,55,.42)}
.conversation-copy strong{display:flex;align-items:center;min-width:0}
.conversation-copy strong>.elite-tier-chip{flex:0 0 auto}
.person-card{position:relative;overflow:hidden}
.person-card.rank-vip{background:linear-gradient(145deg,#fff,#faf7ff)}
.person-card.rank-legend{box-shadow:0 15px 34px rgba(112,0,25,.12)}
.person-card>.elite-tier-chip{margin:5px auto 0}

/* Shared elite banner */
.elite-profile-banner{
  position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;
  margin:18px 24px 2px;padding:13px 15px;border-radius:18px;overflow:hidden;
  border:1px solid rgba(151,112,235,.28);background:linear-gradient(120deg,#f8f4ff,#fff,#f2fbff);
  box-shadow:0 12px 30px rgba(76,52,166,.1);
}
.elite-profile-banner::before{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.92) 47%,transparent 70%);transform:translateX(-120%);animation:eliteBannerSweep 6s ease-in-out infinite}
.elite-profile-banner .elite-profile-emblem{position:relative;z-index:1;width:38px;height:38px;border-radius:12px;display:grid;place-items:center;font:950 19px/1 Inter;color:#fff;background:linear-gradient(145deg,#7357f4,#b75fe9);box-shadow:0 7px 17px rgba(101,72,211,.32)}
.elite-profile-banner>div{position:relative;z-index:1;display:grid}
.elite-profile-banner b{font-size:11px;letter-spacing:.15em;color:#4b348f}
.elite-profile-banner small{font-size:10px;color:#7d7593;margin-top:3px}
.elite-profile-banner>i{position:relative;z-index:1;width:7px;height:7px;border-radius:50%;background:#8d6af0;box-shadow:0 0 0 6px rgba(141,106,240,.1),0 0 18px rgba(141,106,240,.62)}
.elite-profile-banner.tier-legend{border-color:rgba(222,35,69,.34);background:linear-gradient(120deg,#fff6e8,#fff 43%,#fff0f3);box-shadow:0 14px 34px rgba(126,0,28,.14)}
.elite-profile-banner.tier-legend .elite-profile-emblem{background:linear-gradient(145deg,#ff405f,#a60024 60%,#540011);box-shadow:0 0 0 1px rgba(255,216,138,.72),0 8px 20px rgba(137,0,29,.42);animation:legendEmblemFloat 2.8s ease-in-out infinite}
.elite-profile-banner.tier-legend b{color:#8c001f}
.elite-profile-banner.tier-legend>i{background:#d20c35;box-shadow:0 0 0 6px rgba(210,12,53,.1),0 0 20px rgba(210,12,53,.7)}

/* Own and public profile shells */
.profile-modal-card.profile-tier-vip,
.public-profile-card.profile-tier-vip{
  border:1px solid rgba(132,98,238,.4)!important;
  background:linear-gradient(160deg,#fff 0 54%,#fbf8ff 100%);
  box-shadow:0 34px 90px rgba(72,48,160,.25),0 0 0 1px rgba(255,255,255,.65) inset;
}
.profile-modal-card.profile-tier-legend,
.public-profile-card.profile-tier-legend{
  border:1px solid rgba(224,35,70,.46)!important;
  background:linear-gradient(160deg,#fff 0 55%,#fff7f8 100%);
  box-shadow:0 38px 100px rgba(105,0,24,.3),0 0 0 1px rgba(255,216,138,.34) inset;
}
.profile-cover.cover-tier-vip{
  background-color:#654cdf;
  background-image:linear-gradient(125deg,#40309c,#7657ea 48%,#35b7c7);
}
.profile-cover.cover-tier-legend{
  background-color:#780018;
  background-image:radial-gradient(circle at 75% 20%,rgba(255,216,138,.32),transparent 25%),linear-gradient(125deg,#250008,#86001d 48%,#e1264a);
}
.profile-cover.cover-tier-vip::before,
.profile-cover.cover-tier-legend::before{content:"";position:absolute;inset:0;pointer-events:none}
.profile-cover.cover-tier-vip::before{background:radial-gradient(circle at 18% 35%,rgba(255,255,255,.24),transparent 17%),linear-gradient(110deg,transparent 20%,rgba(255,255,255,.14) 46%,transparent 70%);background-size:auto,220% 100%;animation:vipCoverFlow 10s ease-in-out infinite}
.profile-cover.cover-tier-legend::before{background:radial-gradient(circle at 22% 28%,rgba(255,216,138,.34),transparent 16%),radial-gradient(circle at 76% 64%,rgba(255,78,107,.23),transparent 24%),linear-gradient(110deg,transparent 20%,rgba(255,241,207,.2) 47%,transparent 70%);background-size:auto,auto,230% 100%;animation:legendCoverFlow 7s ease-in-out infinite}
