    min-width: 0;
    height: var(--mobile-app-height, 100dvh);
    margin: 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    overflow: hidden;
    grid-template-columns: minmax(0, 1fr) !important;
  }

  .smart-chat-panel,
  .chat-panel {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    height: 100%;
    min-height: 0;
    overflow: hidden;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: var(--mobile-header-height) auto minmax(0, 1fr) auto auto;
    background: #f8f9fd;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .smart-chat-panel::before,
  .smart-chat-header::after,
  .messages {
    animation: none !important;
  }

  .smart-chat-panel::before {
    display: none !important;
  }

  .smart-chat-header,
  .chat-header {
    width: 100%;
    min-width: 0;
    height: var(--mobile-header-height);
    min-height: var(--mobile-header-height);
    padding: max(4px, env(safe-area-inset-top)) 8px 4px;
    display: grid;
    grid-template-columns: 42px 42px minmax(0, 1fr) 42px;
    align-items: center;
    gap: 7px;
    overflow: hidden;
