/* ============================================================
   NexChat V9.0.1 · Admin security activity
   ============================================================ */
.admin-security-activity{
  margin:20px 0;
  padding:22px;
  border:1px solid color-mix(in srgb,var(--primary,#6d5dfc) 18%,transparent);
  border-radius:24px;
  background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(248,248,255,.88));
  box-shadow:0 18px 52px rgba(38,36,78,.08);
}
.admin-security-activity-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:16px}
.admin-security-activity-head h2{margin:4px 0 6px;font-size:clamp(1.15rem,2vw,1.5rem)}
.admin-security-activity-head p{margin:0;color:var(--muted,#73758a);max-width:720px}
.compact-button{min-height:42px;padding:0 15px;display:inline-flex;align-items:center;gap:8px;white-space:nowrap}
.admin-audit-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;max-height:330px;overflow:auto;padding:2px;scrollbar-width:thin}
.admin-audit-item{display:flex;align-items:flex-start;gap:12px;padding:14px;border:1px solid rgba(100,93,180,.12);border-radius:17px;background:rgba(255,255,255,.72);min-width:0}
.admin-audit-icon{display:grid;place-items:center;width:38px;height:38px;flex:0 0 38px;border-radius:13px;color:#6557df;background:linear-gradient(145deg,rgba(109,93,252,.16),rgba(14,165,233,.1))}
.admin-audit-icon .classic-ui-icon{width:19px;height:19px}
.admin-audit-item div{min-width:0}
.admin-audit-item strong{display:block;font-size:.92rem;color:var(--text,#25263b)}
.admin-audit-item p{margin:4px 0;font-size:.82rem;color:var(--muted,#73758a);overflow-wrap:anywhere}
.admin-audit-item small{display:block;font-size:.72rem;color:#9698aa}
body.dark .admin-security-activity{background:linear-gradient(145deg,rgba(34,34,58,.96),rgba(26,27,49,.9));border-color:rgba(139,125,255,.2)}
body.dark .admin-audit-item{background:rgba(255,255,255,.035);border-color:rgba(255,255,255,.07)}
body.dark .admin-audit-item strong{color:#f4f3ff}
@media (max-width:820px){
  .admin-security-activity{margin:14px 12px;padding:16px;border-radius:20px}
  .admin-security-activity-head{align-items:center}
  .admin-security-activity-head p{font-size:.82rem}
  .admin-audit-list{grid-template-columns:1fr;max-height:290px}
  .admin-audit-item{padding:12px;border-radius:15px}
  .compact-button span:not(.classic-icon-host){display:none}
  .compact-button{width:42px;padding:0;justify-content:center}
}

