/* ========================================================================== 
   NexChat V9.1.0 · premium tiers, adaptive scale and unified responsive chat
   ========================================================================== */
:root{
  --ui-scale:1;
  --ui-scale-inverse:1;
  --app-available-height:var(--mobile-app-height,100dvh);
}
body.has-server-announcement.app-page{--app-available-height:calc(var(--mobile-app-height,100dvh) - var(--server-announcement-height,0px))}
body.smart-app-page{width:100vw;max-width:100vw;height:var(--mobile-app-height,100dvh);overflow:hidden!important}
.smart-app-page .app-shell.smart-shell{
  width:calc(100vw / var(--ui-scale))!important;
  max-width:none!important;
  min-width:0!important;
  height:calc(var(--app-available-height) / var(--ui-scale))!important;
  min-height:calc(var(--app-available-height) / var(--ui-scale))!important;
  margin:0!important;
  border-radius:0!important;
  transform:scale(var(--ui-scale));
  transform-origin:top left;
  will-change:transform;
  overflow:hidden!important;
}
.smart-app-page .chat-panel,.smart-app-page .smart-chat-panel{min-width:0;max-width:none;height:100%;overflow:hidden}
.smart-app-page .messages,.smart-app-page .special-panel{min-width:0;max-width:100%}

/* Persistent navigation selection: every workspace keeps a visible active state. */
.smart-sidebar .nav-item{position:relative;isolation:isolate;overflow:hidden}
.smart-sidebar .nav-item::before{
  content:"";position:absolute;left:0;top:12%;bottom:12%;width:4px;border-radius:0 8px 8px 0;
  background:linear-gradient(180deg,#55dcff,#7658ff 52%,#bf5cff);
  box-shadow:0 0 16px rgba(102,89,244,.48);opacity:0;transform:scaleY(.35);transition:.2s ease;z-index:2
}
.smart-sidebar .nav-item.active{
  color:#4f42c5!important;border-color:rgba(103,88,232,.2)!important;
  background:linear-gradient(100deg,rgba(106,89,235,.15),rgba(91,203,237,.07),rgba(255,255,255,.7))!important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.55),0 10px 24px rgba(70,57,154,.1)!important
}
.smart-sidebar .nav-item.active::before{opacity:1;transform:scaleY(1)}
.smart-sidebar .nav-item.active .classic-ui-icon{filter:drop-shadow(0 3px 7px rgba(92,72,215,.28));transform:scale(1.05)}

/* Smart composer delete: visible only when useful and never covers text. */
.composer-clear-button{
