.composer-clear-button .classic-ui-icon{width:16px;height:16px}
.composer-clear-button.hidden{display:none!important}

/* Scale controller. */
.interface-scale-button{position:relative}
.scale-button-glyph{font:900 13px/1 Inter,system-ui;letter-spacing:-.08em;background:linear-gradient(135deg,#493ac9,#8c57ed,#2aafc8);-webkit-background-clip:text;background-clip:text;color:transparent}
