/* ========================================================================== 
   NexChat V9.1.1 · viewport-fit correction
   The shell's previous entrance animation animated `transform`, which
   overrode the scale used to compensate for browser/UI zoom. The layout
   width was divided by the scale but was no longer visually scaled back,
   leaving an empty strip on the right. This rule keeps the fade animation
   while reserving transform exclusively for responsive scaling.
   ========================================================================== */
@keyframes v911ShellViewportFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

html:has(body.smart-app-page),
body.smart-app-page {
  width: 100%;
  max-width: none;
  height: 100%;
  min-height: 0;
  overflow: hidden !important;
}

body.smart-app-page {
  position: fixed;
  inset: 0;
}

.smart-app-page .app-shell.smart-shell {
  width: calc(100vw / var(--ui-scale, 1)) !important;
  max-width: none !important;
  height: calc(var(--app-available-height, 100dvh) / var(--ui-scale, 1)) !important;
  min-height: calc(var(--app-available-height, 100dvh) / var(--ui-scale, 1)) !important;
  margin: 0 !important;
  transform: scale(var(--ui-scale, 1)) !important;
  transform-origin: 0 0 !important;
  animation: v911ShellViewportFade .28s ease-out both !important;
}

/* Keep every internal column bound to the corrected full viewport shell. */
.smart-app-page .sidebar,
.smart-app-page .chat-panel,
.smart-app-page .smart-chat-panel {
  height: 100% !important;
  min-height: 0 !important;
}

@media (max-width: 820px) {
  .smart-app-page .app-shell.smart-shell {
    width: calc(100vw / var(--ui-scale, 1)) !important;
    max-width: none !important;
    transform: scale(var(--ui-scale, 1)) !important;
    transform-origin: 0 0 !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .smart-app-page .app-shell.smart-shell {
    animation: none !important;
  }
}


/* ========================================================================== 
   NexChat V9.1.2 · stable interface scaling without disappearing messages
   Native CSS zoom participates in layout, so scroll containers and message
   geometry remain valid after the user changes the interface size. A transform
   fallback is kept only for browsers without zoom support.
   ========================================================================== */
.smart-app-page .app-shell.smart-shell {
  width: calc(100vw / var(--ui-scale, 1)) !important;
  max-width: none !important;
  height: calc(var(--app-available-height, 100dvh) / var(--ui-scale, 1)) !important;
  min-height: calc(var(--app-available-height, 100dvh) / var(--ui-scale, 1)) !important;
  margin: 0 !important;
  transform-origin: 0 0 !important;
  overflow: hidden !important;
}

@supports (zoom: 1) {
  .smart-app-page .app-shell.smart-shell {
    zoom: var(--ui-scale, 1);
    transform: none !important;
    will-change: auto !important;
  }
}

@supports not (zoom: 1) {
  .smart-app-page .app-shell.smart-shell {
    zoom: 1;
    transform: scale(var(--ui-scale, 1)) !important;
    will-change: transform;
  }
}

.smart-app-page .chat-panel,
.smart-app-page .smart-chat-panel {
  grid-template-rows: auto auto auto auto auto minmax(0, 1fr) auto auto !important;
  height: 100% !important;
  min-height: 0 !important;
  overflow: hidden !important;
}

.smart-app-page .messages,
.smart-app-page .special-panel {
  min-height: 0 !important;
  max-height: none !important;
  overflow-y: auto !important;
  overscroll-behavior: contain;
}

body.interface-scale-changing .messages {
  scroll-behavior: auto !important;
}
body.interface-scale-changing .message-row,
body.interface-scale-changing .message-entry {
  animation: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* Never let a stale performance observer hide the message content itself. */
.performance-optimized .message-row.effects-suspended .message-stack,
.performance-optimized .message-row.effects-suspended .message-bubble,
.performance-optimized .message-row.effects-suspended .message-bubble > p,
.performance-optimized .message-row.effects-suspended .message-meta {
  visibility: visible !important;
  opacity: 1 !important;
}

@media (max-width: 820px) {
  .smart-app-page .app-shell.smart-shell {
    width: calc(100vw / var(--ui-scale, 1)) !important;
    height: calc(var(--app-available-height, 100dvh) / var(--ui-scale, 1)) !important;
  }
}

/* ========================================================================== 
   NexChat V9.1.3 · Royal Crystal V / L emblems
   CSS-only vector monograms: no external image, lightweight on every device.
   ========================================================================== */
@keyframes nexRoyalVipSurface {
  0%,100% { background-position: 0% 45%; filter: saturate(1.04) brightness(1); }
  50% { background-position: 100% 55%; filter: saturate(1.22) brightness(1.09); }
}
@keyframes nexRoyalLegendSurface {
  0%,100% { background-position: 12% 50%; filter: saturate(1.03) brightness(.98); }
  50% { background-position: 88% 50%; filter: saturate(1.18) brightness(1.08); }
}
@keyframes nexRoyalHalo {
  to { transform: rotate(360deg); }
}
@keyframes nexRoyalGlint {
  0%,62%,100% { transform: translateX(-190%) skewX(-24deg); opacity: 0; }
  70% { opacity: .92; }
  83% { transform: translateX(210%) skewX(-24deg); opacity: 0; }
}

/* Shared premium crystal body. */
.profile-rank-badge {
