/* Global theme selector shared by login, chat, support and admin. */
.global-theme-control{position:relative;z-index:1150;flex:0 0 auto}
.global-theme-button{width:40px;height:40px;border:1px solid var(--line);border-radius:13px;display:grid;place-items:center;background:var(--surface);color:var(--text);box-shadow:0 8px 22px rgba(32,29,76,.08);transition:transform .2s var(--theme-ease),border-color .2s ease,background .2s ease}
.global-theme-button:hover{transform:translateY(-1px);border-color:rgba(112,91,225,.45)}
.global-theme-button .classic-ui-icon{width:19px;height:19px}
.global-theme-menu{position:absolute;right:0;top:calc(100% + 10px);width:218px;padding:9px;border:1px solid var(--panel-line);border-radius:17px;background:var(--panel-glass);box-shadow:var(--panel-shadow);backdrop-filter:blur(22px);opacity:0;visibility:hidden;transform:translateY(-6px) scale(.98);transform-origin:top right;transition:.2s var(--theme-ease)}
.global-theme-control.open .global-theme-menu{opacity:1;visibility:visible;transform:none}
.global-theme-menu>span{display:block;padding:5px 8px 8px;color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}
.global-theme-menu>button{width:100%;min-height:48px;border:0;border-radius:12px;padding:8px 9px;display:grid;grid-template-columns:28px 1fr;grid-template-rows:auto auto;column-gap:9px;text-align:left;background:transparent;color:var(--text)}
.global-theme-menu>button:hover,.global-theme-menu>button.active{background:color-mix(in srgb,var(--primary) 12%,transparent)}
.global-theme-menu .classic-ui-icon{grid-row:1/3;width:19px;height:19px;align-self:center;color:var(--primary)}
.global-theme-menu b{font-size:12px}
.global-theme-menu small{font-size:10px;color:var(--muted)}
.auth-card-top .global-theme-control{margin-left:auto;margin-right:8px}
.chat-header-actions .global-theme-control,.admin-topbar-tools .global-theme-control,.support-header-actions .global-theme-control{order:-1}
@media(max-width:640px){.global-theme-menu{position:fixed;right:12px;top:64px;width:min(240px,calc(100vw - 24px))}.global-theme-button{width:38px;height:38px}.auth-card-top .global-theme-control{display:block}}

