/* More distinctive, premium home hero motion. */
.home-hero-signature{display:flex;align-items:center;gap:4px;width:max-content;margin:15px 0 -2px;color:rgba(170,181,215,.65);font-size:8px;font-weight:900;letter-spacing:.18em}
.home-hero-signature i{width:3px;border-radius:999px;background:linear-gradient(#5eead4,#7c5cff);box-shadow:0 0 10px rgba(94,234,212,.35);animation:homeSignal 1.4s ease-in-out infinite}
.home-hero-signature i:nth-child(1){height:9px}.home-hero-signature i:nth-child(2){height:17px;animation-delay:.12s}.home-hero-signature i:nth-child(3){height:12px;animation-delay:.24s}
.home-kinetic-title{position:relative;isolation:isolate}
.home-kinetic-title::after{content:"";position:absolute;left:-2%;right:7%;bottom:-4%;height:24%;z-index:-1;background:radial-gradient(ellipse at center,rgba(96,76,255,.28),transparent 68%);filter:blur(18px);opacity:.7}
.home-kinetic-title>span{display:block;animation:heroHeadlineIn .8s var(--theme-ease) both}
.home-kinetic-title>strong{display:block;background-size:240% 100%!important;animation:heroHeadlineIn .9s var(--theme-ease) .08s both,heroGradientTravel 7s ease-in-out infinite!important}
.home-live-rail{display:flex;align-items:center;gap:7px;height:22px;margin:21px 0 5px;overflow:hidden}
.home-live-rail span{display:block;width:54px;height:1px;background:linear-gradient(90deg,transparent,rgba(112,92,255,.9),rgba(56,190,217,.75),transparent);animation:homeRail 3.8s ease-in-out infinite}
.home-live-rail span:nth-child(2){width:30px;animation-delay:.35s}.home-live-rail span:nth-child(3){width:72px;animation-delay:.7s}.home-live-rail span:nth-child(4){width:24px;animation-delay:1.05s}.home-live-rail span:nth-child(5){width:45px;animation-delay:1.4s}
.home-product-stage::before{content:"";position:absolute;inset:9% 7%;border-radius:50%;background:conic-gradient(from 30deg,transparent,rgba(105,90,255,.18),transparent 28%,rgba(47,190,213,.12),transparent 55%);filter:blur(12px);animation:homeStageAura 16s linear infinite}
.home-phone-card{transform-style:preserve-3d;animation:homePhoneFloat 6.5s ease-in-out infinite}
.home-phone-card::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,.1) 45%,transparent 64%);transform:translateX(-130%);animation:homePhoneSweep 7.5s ease-in-out infinite}
.home-motion-reduced .home-hero-signature i,.home-motion-reduced .home-live-rail span,.home-motion-reduced .home-phone-card,.home-motion-reduced .home-product-stage::before,.home-motion-reduced .home-phone-card::after{animation:none!important}
@keyframes homeSignal{0%,100%{transform:scaleY(.55);opacity:.45}50%{transform:scaleY(1.1);opacity:1}}
@keyframes heroHeadlineIn{from{opacity:0;transform:translateY(22px);filter:blur(7px)}to{opacity:1;transform:none;filter:none}}
@keyframes heroGradientTravel{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
@keyframes homeRail{0%,100%{transform:translateX(-10px);opacity:.18}50%{transform:translateX(12px);opacity:.9}}
@keyframes homeStageAura{to{transform:rotate(360deg)}}
@keyframes homePhoneFloat{0%,100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0)}50%{transform:translate3d(0,-10px,0) rotateX(1deg) rotateY(-1deg)}}
@keyframes homePhoneSweep{0%,67%,100%{transform:translateX(-135%);opacity:0}75%{opacity:.7}87%{transform:translateX(135%);opacity:0}}

/* Professional admin command center. */
.admin-main{background:radial-gradient(circle at 86% 0,rgba(112,88,222,.08),transparent 28%),#f3f4f9}
.admin-sidebar{background:linear-gradient(180deg,#171827,#202135 55%,#171824);border-right:1px solid rgba(255,255,255,.07)}
.admin-sidebar::before{content:"";position:absolute;inset:0 0 auto;height:190px;pointer-events:none;background:radial-gradient(circle at 50% 0,rgba(123,96,255,.18),transparent 68%)}
.admin-sidebar>*{position:relative;z-index:1}
.admin-topbar{min-height:78px!important;padding:0 clamp(16px,2.4vw,30px)!important;box-shadow:0 8px 30px rgba(36,31,87,.05)}
.admin-topbar-title h1{font-size:clamp(20px,2.2vw,29px)!important;letter-spacing:-.04em}
.admin-command-strip{margin:16px clamp(12px,2vw,24px) 2px;padding:15px 17px;border:1px solid rgba(83,79,129,.11);border-radius:20px;background:linear-gradient(135deg,rgba(255,255,255,.95),rgba(247,248,255,.92));box-shadow:0 14px 40px rgba(33,29,85,.07);display:flex;align-items:center;justify-content:space-between;gap:18px;overflow:hidden;position:relative}
.admin-command-strip::after{content:"";position:absolute;inset:auto -8% -80% auto;width:280px;height:180px;border-radius:50%;background:radial-gradient(circle,rgba(109,87,229,.13),transparent 68%);pointer-events:none}
.admin-command-intro{display:flex;align-items:center;gap:12px;min-width:0}
.admin-command-intro>div{display:grid;gap:3px;min-width:0}
.admin-command-intro strong{font-size:13px;letter-spacing:-.01em}
.admin-command-intro small{font-size:9px;color:var(--muted);line-height:1.4}
.admin-command-pulse{width:38px;height:38px;flex:0 0 38px;border-radius:13px;background:radial-gradient(circle at 35% 30%,#99fff0,#38bcaa 28%,#1b7d71 72%);box-shadow:inset 0 1px 0 rgba(255,255,255,.7),0 0 0 6px rgba(57,190,169,.08),0 10px 24px rgba(34,146,130,.22);position:relative}
.admin-command-pulse::before,.admin-command-pulse::after{content:"";position:absolute;inset:50% auto auto 50%;border-radius:50%;transform:translate(-50%,-50%);border:1px solid rgba(255,255,255,.65)}
.admin-command-pulse::before{width:12px;height:12px}.admin-command-pulse::after{width:22px;height:22px;animation:adminPulseRing 2.4s ease-out infinite}
.admin-command-badges{display:flex;align-items:center;gap:7px;flex-wrap:wrap;justify-content:flex-end}
.admin-command-badges span{display:inline-flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid rgba(83,79,129,.1);border-radius:999px;background:rgba(255,255,255,.72);color:#656577;font-size:8px;font-weight:800}
.admin-command-badges i{width:6px;height:6px;border-radius:50%;background:#4ec6a3;box-shadow:0 0 0 4px rgba(78,198,163,.1)}
html[data-theme="dark"] .admin-command-badges span{background:rgba(255,255,255,.04);color:#bbbacc}
.stats-grid.admin-stats-extended{padding-top:16px!important;gap:11px!important}
.stats-grid.admin-stats-extended article{position:relative;overflow:hidden;border:1px solid rgba(83,79,129,.1)!important;border-radius:19px!important;box-shadow:0 14px 35px rgba(37,32,88,.06)!important;transition:transform .24s var(--theme-ease),box-shadow .24s ease}
.stats-grid.admin-stats-extended article::after{content:"";position:absolute;right:-18px;top:-24px;width:80px;height:80px;border-radius:50%;background:radial-gradient(circle,rgba(108,86,225,.12),transparent 68%)}
.stats-grid.admin-stats-extended article:hover{transform:translateY(-3px);box-shadow:0 20px 45px rgba(37,32,88,.1)!important}
.admin-audit-actions{display:flex;gap:8px;align-items:center}
.audit-clear-button{color:#c63d56!important;border-color:rgba(211,61,86,.2)!important;background:#fff7f8!important}
.audit-clear-button:hover{background:#fff0f2!important;border-color:rgba(211,61,86,.35)!important}
.admin-clear-audit-card{border:1px solid rgba(217,70,92,.15);background:linear-gradient(160deg,#fff,#fff9fa)}
.admin-modal-kicker{display:block;margin:14px 0 5px;color:#c23a54;font-size:9px;font-weight:950;letter-spacing:.16em}
html[data-theme="dark"] .admin-clear-audit-card{background:linear-gradient(160deg,#221d28,#191a25)}
@keyframes adminPulseRing{0%{opacity:.9;transform:translate(-50%,-50%) scale(.8)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.55)}}
@media(max-width:920px){.admin-command-strip{align-items:flex-start;flex-direction:column}.admin-command-badges{justify-content:flex-start}.admin-audit-actions{width:100%;justify-content:flex-end}}
@media(max-width:560px){.admin-command-strip{margin:10px;padding:13px;border-radius:17px}.admin-command-badges span{font-size:7px}.admin-security-activity-head{align-items:flex-start;flex-direction:column}.admin-audit-actions{justify-content:stretch}.admin-audit-actions button{flex:1}}

/* Realistic faceted jewel system: subdued, photographic and not cartoon-like. */
@keyframes jewelGlint{0%,70%,100%{transform:translateX(-180%) skewX(-18deg);opacity:0}77%{opacity:.72}88%{transform:translateX(180%) skewX(-18deg);opacity:0}}
@keyframes jewelBreathe{0%,100%{filter:brightness(.98) contrast(1.04)}50%{filter:brightness(1.07) contrast(1.08)}}
.profile-rank-badge>i{display:none!important}
.profile-rank-badge,
.premium-rank-symbol,
.elite-tier-chip>i,
.privilege-time-emblem,
.message-rank-mark,
.elite-profile-emblem,
.home-tier-emblem,
.home-v-badge,
.home-l-badge{
  --jewel-cut:polygon(50% 0,78% 8%,96% 30%,100% 55%,84% 82%,50% 100%,16% 82%,0 55%,4% 30%,22% 8%);
  --jewel-edge:rgba(255,255,255,.7);
  position:relative!important;
  isolation:isolate!important;
  overflow:hidden!important;
  border:0!important;
  border-radius:0!important;
  clip-path:var(--jewel-cut)!important;
  background:transparent!important;
  box-shadow:none!important;
  text-shadow:none!important;
}
.profile-rank-badge::before,
.premium-rank-symbol::before,
.elite-tier-chip>i::before,
.privilege-time-emblem::before,
.message-rank-mark::before,
.elite-profile-emblem::before,
.home-tier-emblem::before,
.home-v-badge::before,
.home-l-badge::before{
  content:""!important;position:absolute!important;inset:0!important;z-index:0!important;clip-path:inherit!important;border-radius:0!important;
  background:
    linear-gradient(133deg,rgba(255,255,255,.9) 0 5%,transparent 6% 35%,rgba(255,255,255,.22) 36% 39%,transparent 40%),
    linear-gradient(42deg,transparent 0 39%,rgba(255,255,255,.18) 40% 43%,transparent 44%),
    conic-gradient(from 17deg at 50% 52%,var(--facet-1) 0 11%,var(--facet-2) 11% 23%,var(--facet-3) 23% 36%,var(--facet-4) 36% 49%,var(--facet-2) 49% 63%,var(--facet-5) 63% 76%,var(--facet-3) 76% 88%,var(--facet-1) 88% 100%)!important;
  background-blend-mode:screen,overlay,normal!important;
  box-shadow:inset 0 0 0 1px var(--jewel-edge),inset 0 -7px 14px rgba(3,5,18,.42),inset 0 5px 9px rgba(255,255,255,.18)!important;
  animation:jewelBreathe 5.8s ease-in-out infinite!important;
}
.profile-rank-badge::after,
.premium-rank-symbol::after,
.elite-tier-chip>i::after,
.privilege-time-emblem::after,
.message-rank-mark::after,
.elite-profile-emblem::after,
.home-tier-emblem::after,
.home-v-badge::after,
.home-l-badge::after{
  content:""!important;position:absolute!important;z-index:2!important;inset:-18% auto -18% -42%!important;width:34%!important;height:auto!important;top:-18%!important;left:-42%!important;border-radius:0!important;clip-path:none!important;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.88),transparent)!important;filter:blur(.4px)!important;animation:jewelGlint 7.8s ease-in-out infinite!important;
}
.profile-rank-vip,
.symbol-vip,
.elite-tier-chip.tier-vip>i,
.privilege-vip .privilege-time-emblem,
.message-rank-mark.mark-vip,
.home-tier-v,
.home-v-badge{
  --facet-1:#eff5ff;--facet-2:#9da8ca;--facet-3:#5f5e9f;--facet-4:#cdd5f0;--facet-5:#6b4d92;--jewel-edge:rgba(244,247,255,.82);
  filter:drop-shadow(0 6px 9px rgba(23,25,56,.38)) drop-shadow(0 0 7px rgba(135,130,210,.16))!important;
}
.profile-rank-legend,
.symbol-legend,
.elite-tier-chip.tier-legend>i,
.privilege-legend .privilege-time-emblem,
.message-rank-mark.mark-legend,
.home-tier-l,
.home-l-badge,
.elite-profile-banner.tier-legend .elite-profile-emblem{
  --facet-1:#fff4ca;--facet-2:#c7953f;--facet-3:#64303a;--facet-4:#e1b65f;--facet-5:#27131a;--jewel-edge:rgba(255,231,168,.82);
  filter:drop-shadow(0 7px 10px rgba(42,15,23,.5)) drop-shadow(0 0 8px rgba(205,152,64,.18))!important;
}
.profile-rank-badge>b{position:relative!important;z-index:4!important;color:transparent!important;font-size:0!important;text-shadow:none!important}
.profile-rank-badge>b::before,
.profile-rank-badge>b::after,
.premium-rank-symbol span::before,
.premium-rank-symbol span::after{filter:none!important}
/* Keep existing CSS-built V/L strokes, but make them look like engraved platinum/gold. */
.profile-rank-vip>b::before,.profile-rank-vip>b::after,
.symbol-vip::before,.symbol-vip::after,
.elite-tier-chip.tier-vip>i::before,.elite-tier-chip.tier-vip>i::after,
.privilege-vip .privilege-time-emblem::before,.privilege-vip .privilege-time-emblem::after,
.message-rank-mark.mark-vip::before,.message-rank-mark.mark-vip::after{
