.profile-rank-legend>b::before,.profile-rank-legend>b::after,
.symbol-legend::before,.symbol-legend::after,
.elite-tier-chip.tier-legend>i::before,.elite-tier-chip.tier-legend>i::after,
.privilege-legend .privilege-time-emblem::before,.privilege-legend .privilege-time-emblem::after,
.message-rank-mark.mark-legend::before,.message-rank-mark.mark-legend::after{
  z-index:4!important;background:linear-gradient(180deg,#fff8d9 0%,#e7bd62 36%,#9a6627 68%,#ffe9a8 100%)!important;box-shadow:inset 0 1px 0 #fff6d1,0 1px 2px rgba(38,13,18,.8)!important;filter:drop-shadow(0 0 1px rgba(255,229,151,.8))!important}
.badge-admin-metrics>div:has(.profile-rank-vip),.badge-admin-metrics>div:has(.profile-rank-legend){background:linear-gradient(145deg,rgba(255,255,255,.94),rgba(247,247,252,.9))!important;border-color:rgba(87,84,111,.14)!important}
.home-tier-emblem{display:grid!important;place-items:center!important;color:#fff!important;font:900 24px/1 Inter,system-ui!important;letter-spacing:-.08em!important}
.home-tier-emblem::before{z-index:-1!important}
.home-v-badge,.home-l-badge{display:inline-grid!important;place-items:center!important;color:#fff!important;font:900 9px/1 Inter,system-ui!important}
.performance-lite .profile-rank-badge::before,
.performance-lite .premium-rank-symbol::before,
.performance-lite .elite-tier-chip>i::before,
.performance-lite .privilege-time-emblem::before,
.performance-lite .message-rank-mark::before,
.performance-lite .profile-rank-badge::after,
.performance-lite .premium-rank-symbol::after,
.performance-lite .elite-tier-chip>i::after,
.performance-lite .privilege-time-emblem::after,
.performance-lite .message-rank-mark::after{animation:none!important}
@media(prefers-reduced-motion:reduce){.profile-rank-badge::before,.profile-rank-badge::after,.premium-rank-symbol::before,.premium-rank-symbol::after,.elite-tier-chip>i::before,.elite-tier-chip>i::after,.privilege-time-emblem::before,.privilege-time-emblem::after,.message-rank-mark::before,.message-rank-mark::after{animation:none!important}}
/* Direct jewel hosts use the element itself as the gemstone; their two pseudo-elements remain the V/L inlay. */
.premium-rank-symbol,
