/* =========================================================
   NexChat V9.3.1 · compact login and adaptive auth layout
   ========================================================= */
.auth-showcase{
  justify-content:stretch;
}
.auth-showcase-top{
  flex:0 0 auto;
}
.auth-showcase .showcase-copy{
  margin:auto 0;
  padding-block:clamp(34px,8vh,96px);
  max-width:min(620px,100%);
}
.auth-showcase .showcase-copy::after{
  width:clamp(170px,22vw,260px);
  height:clamp(170px,22vw,260px);
}

.login-options-row.login-options-compact{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  min-width:0;
  margin-top:-4px;
}
.remember-login-compact{
  display:inline-flex;
  align-items:center;
  gap:8px;
  width:auto;
  min-width:0;
  min-height:30px;
  padding:3px 0;
  border:0!important;
  border-radius:0;
  background:transparent!important;
  box-shadow:none!important;
  color:var(--text);
  cursor:pointer;
  user-select:none;
  -webkit-tap-highlight-color:transparent;
}
.remember-login-compact:hover,
.remember-login-compact:active{
  border:0!important;
  background:transparent!important;
  box-shadow:none!important;
  transform:none!important;
}
.remember-login-compact:focus-within{
  outline:2px solid color-mix(in srgb,var(--primary) 26%,transparent);
  outline-offset:4px;
  border-radius:8px;
}
.remember-login-compact>input{
  position:absolute;
  width:1px;
  height:1px;
  opacity:0;
  pointer-events:none;
}
.remember-login-compact .remember-login-copy{
  display:block;
  min-width:0;
  line-height:1;
}
.remember-login-compact .remember-login-copy strong{
  display:block;
  color:var(--text);
  font-size:11px;
  font-weight:800;
  white-space:nowrap;
}
.remember-login-compact .remember-login-copy small,
.remember-login-compact .remember-login-safe{
  display:none!important;
}
.remember-login-switch{
  position:relative;
  display:block;
  width:31px!important;
  height:18px!important;
  flex:0 0 31px!important;
  padding:2px!important;
  border:0!important;
  border-radius:999px;
  background:#d9dbe6;
  box-shadow:inset 0 0 0 1px rgba(45,45,70,.08);
  transition:background .18s ease,box-shadow .18s ease;
}
.remember-login-switch i{
  display:block;
  width:14px!important;
  height:14px!important;
  border-radius:50%;
  background:#fff;
  box-shadow:0 2px 6px rgba(26,27,48,.24);
  transform:translateX(0);
  transition:transform .2s cubic-bezier(.2,.8,.2,1);
}
.remember-login-compact input:checked~.remember-login-switch{
  background:linear-gradient(135deg,#6557e8,#8a5be7);
  box-shadow:0 4px 12px rgba(101,87,232,.24);
}
.remember-login-compact input:checked~.remember-login-switch i{
  transform:translateX(13px)!important;
}
html[data-theme="dark"] .remember-login-compact{
  background:transparent!important;
  border:0!important;
}
html[data-theme="dark"] .remember-login-switch{
  background:#404254;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.08);
}
.forgot-account-link{
  min-height:30px;
  display:inline-flex;
  align-items:center;
  justify-content:flex-end;
