.home-option-label strong{display:flex!important;align-items:center;gap:7px}
.home-option-label strong>b{width:19px;height:19px;display:grid;place-items:center;border-radius:6px;background:color-mix(in srgb,var(--home-purple) 13%,var(--home-surface));color:var(--home-purple);font-size:9px}
