  --badge-motion-soft:255,176,66;
}
.badge-admin-metrics>div>*{
  position:relative;
  z-index:2;
}
.badge-admin-metrics>div::before{
  content:"";
  position:absolute;
  z-index:0;
  left:-42px;
  top:50%;
  width:124px;
  height:124px;
  border-radius:50%;
  background:
    radial-gradient(circle at 50% 50%,rgba(var(--badge-motion-soft),.24) 0 23%,transparent 56%),
