  z-index:1;
  top:-55%;
  bottom:-55%;
  left:-46%;
  width:25%;
  border-radius:999px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.72),transparent);
  opacity:0;
  transform:translate3d(-190%,0,0) rotate(17deg);
  pointer-events:none;
