  scroll-behavior:smooth;
  overscroll-behavior:contain;
}
html[data-admin-theme] body.admin-page.admin-cyberpunk :is(
  .admin-command-strip,.account-capacity-card,.admin-security-activity,
  .system-admin-console,.effect-admin-console,.badge-admin-console,
  .admin-workspace,.admin-empty,.system-control-card,.world-config-surface,
  .world-admin-message-form,.announcement-control-card,.support-moderation-card
){
  transition:border-color .22s ease,box-shadow .22s ease,background-color .22s ease,transform .22s var(--admin-theme-ease);
}
@media (hover:hover) and (pointer:fine) and (min-width:901px){
  html[data-admin-theme] body.admin-page.admin-cyberpunk :is(
    .admin-command-strip,.account-capacity-card,.admin-security-activity,
    .system-admin-console,.effect-admin-console,.badge-admin-console,.admin-workspace
  ):hover{
    transform:translateY(-2px);
  }
}

/* Admin-specific selector: two resolved appearances plus Auto. */
