/* Inner energy is alpha-masked to the exact V/L letter shape. */
.profile-rank-badge::before,
.premium-rank-symbol::before,
.elite-tier-chip>i::before,
.privilege-time-emblem::before,
.message-rank-mark::before,
.elite-profile-emblem::before,
.home-tier-emblem::before,
.home-v-badge::before,
.home-l-badge::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  inset:3%!important;
  z-index:2!important;
  pointer-events:none!important;
  border:0!important;
  border-radius:0!important;
  background:
    radial-gradient(circle at 22% 22%,rgba(255,255,255,.94) 0 2.2%,transparent 7%),
    linear-gradient(112deg,transparent 14%,rgba(var(--emblem-core),.10) 31%,rgba(255,255,255,.96) 46%,rgba(var(--emblem-gold),.72) 51%,rgba(var(--emblem-core),.28) 58%,transparent 72%),
