/* NexChat V1.0.0 · immersive conversation wallpaper atmospheres */
.messages.private-theme{background-repeat:no-repeat;background-size:cover;isolation:isolate}
.messages.private-theme::after{
  content:"";position:fixed;pointer-events:none;inset:70px 0 82px 330px;z-index:0;opacity:.75;
  background-repeat:no-repeat;background-size:140% 140%,120% 120%,100% 100%;
  mix-blend-mode:screen;animation:chatWallpaperDrift 18s ease-in-out infinite alternate;
}
.messages.theme-aurora::after{background-image:
  radial-gradient(circle at 18% 24%,rgba(93,255,234,.20),transparent 26%),
  radial-gradient(circle at 84% 20%,rgba(122,198,255,.18),transparent 30%),
