/* NexChat V1.0.0 · adaptive smoothness and interaction frame budget */
:root{
  --nex-ease-standard:cubic-bezier(.2,.72,.24,1);
  --nex-ease-emphasized:cubic-bezier(.16,1,.3,1);
  --nex-ease-exit:cubic-bezier(.4,0,1,1);
  --nex-motion-fast:140ms;
  --nex-motion-ui:220ms;
  --nex-motion-panel:320ms;
  --runtime-motion-scale:1;
}
html[data-runtime-quality="balanced"]{
  --nex-motion-fast:130ms;
  --nex-motion-ui:205ms;
  --nex-motion-panel:290ms;
}
html[data-runtime-quality="limited"]{
  --nex-motion-fast:115ms;
  --nex-motion-ui:180ms;
  --nex-motion-panel:250ms;
}
:is(button,a,[role="button"],.theme-card,.motion-surface,.modal-card,.message-bubble,.nav-item,.home-feature-card,.home-tier-card,.stats-grid>article){
  transition-timing-function:var(--nex-ease-standard)!important;
}
:is(.modal-card,.v10-motion-panel,.global-theme-menu,.sidebar-theme-panel,.conversation-empty-state){
  transition-timing-function:var(--nex-ease-emphasized)!important;
}
:is(button,a,[role="button"],input,textarea,select){-webkit-tap-highlight-color:transparent}
:is(button,a,[role="button"]){touch-action:manipulation}
:is(.messages,.smart-sidebar,.sidebar,.admin-sidebar,.admin-main,.modal-card,.v10-motion-scroll){
  overscroll-behavior:contain;
}
@supports(scrollbar-gutter:stable){
  :is(.messages,.smart-sidebar,.admin-main,.v10-motion-scroll){scrollbar-gutter:stable}
}
.modal-backdrop:not(.hidden) .modal-card,
.v10-motion-backdrop.is-open .v10-motion-panel,
.sidebar.open,.sidebar.is-open,.admin-sidebar.open,.admin-sidebar.is-open,
.global-theme-menu.is-open,.sidebar-theme-panel.is-open{
  will-change:transform,opacity;
  backface-visibility:hidden;
}
.theme-card-preview,.effect-preview-stage,.home-visual-shell,.admin-command-strip,.stats-grid>article{
  contain:layout style paint;
}
body.admin-page :is(.admin-security-activity,.admin-report-center,.effect-admin-console,.badge-admin-console){
  content-visibility:auto;
