/* Keep wallpaper layers inside the chat scroller instead of forcing viewport-wide repaints. */
.messages.private-theme::before,.messages.private-theme::after{
  position:absolute!important;
  inset:0!important;
  transform:translateZ(0);
}
/* During active scrolling, freeze only decorative animation layers. Interaction stays fully live. */
html[data-runtime-scrolling="true"] :is(
  .v10-cosmos-star,.v10-cosmos-meteor,.v10-sidebar-star,.v10-sidebar-meteor,
  .v10-cosmos-nebula,.v11-cosmos-ribbon,.v10-sidebar-nebula,.v10-sidebar-aurora,
  .admin-atmosphere-cloud,.admin-atmosphere-nebula,.admin-atmosphere-ribbon,
  .admin-atmosphere-stars,.admin-atmosphere-particles,.admin-atmosphere-meteors,
  .messages.private-theme::after,.message-bubble[class*="effect-"]
){animation-play-state:paused!important}
html[data-page-visibility="hidden"] *,body.runtime-paused *{animation-play-state:paused!important}
/* Adaptive particle budget: preserve the scene while reducing compositing pressure on weak devices. */
html[data-runtime-quality="limited"] :is(.v10-cosmos-star:nth-of-type(2n),.v10-sidebar-star:nth-of-type(2n)){
  animation-play-state:paused!important;opacity:.22!important;
}
html[data-runtime-quality="limited"] :is(.v10-cosmos-meteor:nth-of-type(n+4),.v10-sidebar-meteor:nth-of-type(n+3)){
  display:none!important;
}
html[data-runtime-quality="limited"] :is(.admin-atmosphere-particles,.admin-atmosphere-grid,.v10-cosmos-grid){
  opacity:.42!important;
}
html[data-runtime-quality="balanced"] .messages.private-theme::after{animation-duration:24s!important}
html[data-runtime-quality="limited"] .messages.private-theme::after{animation-duration:32s!important;opacity:.58!important}
/* Avoid expensive hover compositing on touch devices while retaining keyboard focus feedback. */
@media(hover:none){
  :is(.theme-card,.home-feature-card,.home-tier-card,.stats-grid>article):hover{transform:none!important}
}
@media(prefers-reduced-motion:reduce){
  :root{--nex-motion-fast:1ms;--nex-motion-ui:1ms;--nex-motion-panel:1ms}
  html{scroll-behavior:auto!important}
  .messages.private-theme::after{animation:none!important}
}


