/* =========================================================
   NexChat V1.0.0 · Notification option color cues
   Each control has a restrained accent so users can scan it quickly.
   ========================================================= */
.notification-switch-card{
  --notification-accent:#7187ff;
  --notification-accent-rgb:113,135,255;
  position:relative;
  isolation:isolate;
  overflow:hidden;
  border-color:rgba(var(--notification-accent-rgb),.22);
  background:linear-gradient(135deg,rgba(var(--notification-accent-rgb),.075),rgba(126,139,182,.035));
  box-shadow:inset 3px 0 0 rgba(var(--notification-accent-rgb),.78),0 8px 22px rgba(var(--notification-accent-rgb),.035);
  transition:border-color .2s ease,background .2s ease,box-shadow .2s ease,transform .2s ease;
}
.notification-switch-card::before{
  content:"";
  position:absolute;
  z-index:-1;
  top:-28px;
  left:-18px;
  width:92px;
  height:92px;
  border-radius:50%;
  background:rgba(var(--notification-accent-rgb),.10);
  filter:blur(20px);
  pointer-events:none;
}
.notification-switch-card::after{
  content:"";
  position:absolute;
  top:0;
  left:16px;
  width:44px;
  height:2px;
  border-radius:0 0 999px 999px;
  background:var(--notification-accent);
  box-shadow:0 0 10px rgba(var(--notification-accent-rgb),.58);
  pointer-events:none;
}
.notification-switch-card.notification-tone-blue{--notification-accent:#67a2ff;--notification-accent-rgb:103,162,255}
.notification-switch-card.notification-tone-purple{--notification-accent:#a985ff;--notification-accent-rgb:169,133,255}
.notification-switch-card.notification-tone-amber{--notification-accent:#ffb44f;--notification-accent-rgb:255,180,79}
.notification-switch-card.notification-tone-cyan{--notification-accent:#48d7d2;--notification-accent-rgb:72,215,210}
.notification-switch-card strong{
  display:flex;
  align-items:center;
  gap:7px;
}
.notification-switch-card strong::before{
  content:"";
  flex:0 0 auto;
  width:6px;
  height:6px;
  border-radius:50%;
  background:var(--notification-accent);
  box-shadow:0 0 0 3px rgba(var(--notification-accent-rgb),.11),0 0 8px rgba(var(--notification-accent-rgb),.42);
}
.notification-switch-card .notification-switch-ui{
  background:rgba(var(--notification-accent-rgb),.14);
  box-shadow:inset 0 0 0 1px rgba(var(--notification-accent-rgb),.22);
}
.notification-switch-card input:checked+.notification-switch-ui{
  background:linear-gradient(90deg,rgba(var(--notification-accent-rgb),.76),var(--notification-accent));
  box-shadow:0 5px 14px rgba(var(--notification-accent-rgb),.22),inset 0 0 0 1px rgba(255,255,255,.16);
}
.notification-switch-card:has(input:checked){
  border-color:rgba(var(--notification-accent-rgb),.44);
  background:linear-gradient(135deg,rgba(var(--notification-accent-rgb),.13),rgba(var(--notification-accent-rgb),.045));
  box-shadow:inset 3px 0 0 var(--notification-accent),0 10px 25px rgba(var(--notification-accent-rgb),.08);
}
.notification-switch-card input:focus-visible+.notification-switch-ui{
  outline:2px solid rgba(var(--notification-accent-rgb),.72);
  outline-offset:3px;
}
@media(hover:hover){
  .notification-switch-card:hover{
    transform:translateY(-1px);
    border-color:rgba(var(--notification-accent-rgb),.36);
    background:linear-gradient(135deg,rgba(var(--notification-accent-rgb),.11),rgba(126,139,182,.045));
  }
}
html[data-theme="dark"] body.smart-app-page .notification-switch-card{
  border-color:rgba(var(--notification-accent-rgb),.24)!important;
  background:linear-gradient(135deg,rgba(var(--notification-accent-rgb),.10),rgba(24,30,54,.82) 62%)!important;
}
html[data-theme="dark"] body.smart-app-page .notification-switch-card:has(input:checked){
  border-color:rgba(var(--notification-accent-rgb),.48)!important;
  background:linear-gradient(135deg,rgba(var(--notification-accent-rgb),.16),rgba(24,30,54,.88) 68%)!important;
}
html[data-theme="dark"] body.smart-app-page .notification-switch-card .notification-switch-ui{
  background:rgba(var(--notification-accent-rgb),.15);
}
html[data-theme="dark"] body.smart-app-page .notification-switch-card input:checked+.notification-switch-ui{
  background:linear-gradient(90deg,rgba(var(--notification-accent-rgb),.78),var(--notification-accent));
}
@media(max-width:560px){
  .notification-switch-card strong{gap:6px}
  .notification-switch-card strong::before{width:5px;height:5px}
}


