/* ======================================================================
   NexChat V1.0.0 · Messenger-style hold-to-record voice messages
   One gesture: hold the microphone, release to send, slide left to cancel,
   or slide up to lock. The normal composer is replaced only while recording.
   ====================================================================== */
.voice-record-button{
  position:relative!important;
  display:grid!important;
  place-items:center!important;
  flex:0 0 46px!important;
  width:46px!important;
  height:46px!important;
  min-width:46px!important;
  min-height:46px!important;
  padding:0!important;
  border-radius:15px!important;
  color:#f4f6ff!important;
  border:1px solid rgba(122,105,255,.24)!important;
  background:linear-gradient(145deg,rgba(105,86,231,.92),rgba(65,173,221,.84))!important;
  box-shadow:0 10px 24px rgba(65,75,180,.22),inset 0 1px rgba(255,255,255,.26)!important;
  touch-action:none!important;
  -webkit-user-select:none!important;
  user-select:none!important;
  cursor:pointer!important;
  transition:transform .18s ease,box-shadow .18s ease,filter .18s ease!important;
}
.voice-record-button:hover{filter:brightness(1.06);box-shadow:0 13px 29px rgba(65,75,180,.28),inset 0 1px rgba(255,255,255,.3)!important}
.voice-record-button:active{transform:scale(.92)!important}
.voice-record-button:disabled{opacity:.42!important;cursor:not-allowed!important;filter:saturate(.55)!important}
.voice-record-button .classic-ui-icon,.voice-record-button .classic-icon-host{width:20px!important;height:20px!important}
.voice-record-button.voice-record-attention{animation:voiceRecordAttention .85s cubic-bezier(.2,.9,.2,1)}
@keyframes voiceRecordAttention{0%,100%{transform:scale(1)}35%{transform:scale(1.12);box-shadow:0 0 0 8px rgba(106,93,241,.14),0 15px 32px rgba(62,83,188,.3)}65%{transform:scale(.98)}}

.composer-wrap{position:relative!important}
.composer-wrap.voice-recording-active .smart-composer{opacity:0!important;pointer-events:none!important}
.composer-wrap.voice-recording-active #attachmentPreview,
.composer-wrap.voice-recording-active #emojiPicker,
.composer-wrap.voice-recording-active #quickTools,
.composer-wrap.voice-recording-active #effectActivationDock{display:none!important}
.voice-recorder-bar{
  position:absolute;
  inset-inline:0;
  bottom:0;
  z-index:18;
  display:grid;
  grid-template-columns:42px 16px minmax(0,1fr) 36px 42px;
  align-items:center;
  gap:9px;
  width:100%;
  min-height:60px;
  padding:8px 10px;
  border:1px solid rgba(120,107,237,.24);
  border-radius:19px;
  overflow:hidden;
  isolation:isolate;
  background:
    radial-gradient(circle at 9% 0%,rgba(115,91,239,.17),transparent 38%),
    radial-gradient(circle at 88% 100%,rgba(44,198,222,.10),transparent 34%),
    linear-gradient(145deg,rgba(22,27,55,.98),rgba(12,17,37,.99));
  box-shadow:0 14px 34px rgba(4,8,28,.28),inset 0 1px rgba(255,255,255,.055);
}
.voice-recorder-bar::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:-1;
  pointer-events:none;
  opacity:.45;
  background:linear-gradient(110deg,transparent 18%,rgba(255,255,255,.06) 48%,transparent 78%);
  transform:translateX(-75%);
  animation:voiceRecorderSweep 3.2s ease-in-out infinite;
}
.voice-recorder-bar.is-starting::before{animation-duration:1.6s}
.voice-recorder-bar.is-cancel-armed{
  border-color:rgba(255,105,125,.42);
  background:linear-gradient(145deg,rgba(64,22,42,.98),rgba(30,16,33,.99));
}
.voice-recorder-bar.is-locked{border-color:rgba(83,221,179,.34);background:linear-gradient(145deg,rgba(21,45,53,.98),rgba(13,24,42,.99))}
@keyframes voiceRecorderSweep{0%,24%{transform:translateX(-90%);opacity:.12}58%{opacity:.5}100%{transform:translateX(110%);opacity:.08}}
.voice-record-action{
  display:grid;
  place-items:center;
  width:42px;
  height:42px;
  min-width:42px;
  padding:0;
  border-radius:13px;
  border:1px solid rgba(255,255,255,.09);
  color:#f5f6ff;
  background:rgba(255,255,255,.045);
  opacity:0;
  visibility:hidden;
  pointer-events:none;
  transform:scale(.84);
  transition:opacity .18s ease,visibility .18s ease,transform .2s cubic-bezier(.2,.9,.2,1),background .18s ease;
}
.voice-recorder-bar.is-locked .voice-record-action{opacity:1;visibility:visible;pointer-events:auto;transform:scale(1)}
.voice-record-cancel{color:#ff9cab;background:rgba(255,82,111,.09);border-color:rgba(255,106,129,.15)}
.voice-record-send{color:#071c18;background:linear-gradient(145deg,#61e3b7,#49cfe0);border-color:rgba(132,255,226,.42);box-shadow:0 8px 20px rgba(57,209,181,.22)}
.voice-record-action:hover{transform:translateY(-1px) scale(1.03)!important}
.voice-record-live{position:relative;display:grid;place-items:center;width:16px;height:16px}
.voice-record-live::before{content:"";position:absolute;inset:1px;border-radius:50%;background:rgba(255,91,118,.18);animation:voiceLiveHalo 1.4s ease-out infinite}
.voice-record-live>i{position:relative;width:8px;height:8px;border-radius:50%;background:#ff5577;box-shadow:0 0 12px rgba(255,85,119,.58)}
.voice-recorder-bar.is-locked .voice-record-live>i{background:#52e0b1;box-shadow:0 0 12px rgba(82,224,177,.48)}
.voice-recorder-bar.is-locked .voice-record-live::before{background:rgba(82,224,177,.16)}
@keyframes voiceLiveHalo{0%{transform:scale(.65);opacity:.9}100%{transform:scale(1.7);opacity:0}}
.voice-record-main{display:grid;grid-template-rows:auto 19px auto;gap:3px;min-width:0}
.voice-record-topline{display:flex;align-items:center;gap:8px;min-width:0}
.voice-record-topline strong{color:#fff;font-size:12px;line-height:1;font-variant-numeric:tabular-nums;letter-spacing:.04em}
.voice-record-topline span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#c8cee2;font-size:9px;font-weight:800}
.voice-record-waveform{display:flex;align-items:center;gap:2px;height:19px;min-width:0;overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent);-webkit-mask-image:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent)}
.voice-record-waveform>i{flex:1 1 0;min-width:2px;max-width:4px;height:28%;border-radius:999px;background:linear-gradient(180deg,#8b7cff,#50d7e6);box-shadow:0 0 6px rgba(85,188,235,.18);transition:height .085s linear}
.voice-recorder-bar.is-cancel-armed .voice-record-waveform>i{background:linear-gradient(180deg,#ff859b,#ff526f)}
.voice-recorder-bar.is-locked .voice-record-waveform>i{background:linear-gradient(180deg,#76e7bd,#4acfe0)}
.voice-record-main>small{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#8f98b3;font-size:8px;line-height:1.25}
.voice-recorder-bar.is-cancel-armed .voice-record-main>small{color:#ff9aae;font-weight:800}
.voice-recorder-bar.is-locked .voice-record-main>small{color:#79dfc2}
.voice-record-lock{display:grid;place-items:center;width:34px;height:34px;border-radius:12px;color:#b8b1ff;background:rgba(113,95,227,.10);border:1px solid rgba(133,119,240,.12);animation:voiceLockNudge 1.8s ease-in-out infinite}
.voice-recorder-bar.is-locked .voice-record-lock{opacity:0;visibility:hidden;animation:none}
@keyframes voiceLockNudge{0%,100%{transform:translateY(2px);opacity:.66}50%{transform:translateY(-3px);opacity:1}}

